// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { IDeviationBoundedOracle } from "@venusprotocol/oracle/contracts/interfaces/IDeviationBoundedOracle.sol";

import { ComptrollerInterface, Action } from "../ComptrollerInterface.sol";
import { VToken } from "../VToken.sol";

/**
 * @title SpokeComptrollerInterface
 * @author Venus
 * @notice Interface implemented by the `SpokeComptroller` contract. It declares the events and errors that make up the
 * contract's observable surface, so integrators and off-chain consumers can decode them without depending on the
 * implementation.
 * @dev The getters this fork adds are declared separately, in `SpokeComptrollerViewInterface` below. They cannot live
 * here: `SpokeComptroller` implements this interface, and it serves those getters from public variables declared in
 * `SpokeComptrollerStorage`, which is a sibling base rather than a derived one. Solidity will not let a public
 * variable in one base satisfy a function declared in another, so declaring them here would force
 * `SpokeComptrollerStorage` to inherit this interface and mark six variables `override` - noise in the file that has
 * to be diffed by hand against `ComptrollerStorage`, for no gain over a standalone view interface.
 */
interface SpokeComptrollerInterface is ComptrollerInterface {
    /// @notice Emitted when an account enters a market
    event MarketEntered(VToken indexed vToken, address indexed account);

    /// @notice Emitted when an account exits a market
    event MarketExited(VToken indexed vToken, address indexed account);

    /// @notice Emitted when close factor is changed by admin
    event NewCloseFactor(uint256 oldCloseFactorMantissa, uint256 newCloseFactorMantissa);

    /// @notice Emitted when a collateral factor is changed by admin
    event NewCollateralFactor(VToken vToken, uint256 oldCollateralFactorMantissa, uint256 newCollateralFactorMantissa);

    /// @notice Emitted when liquidation threshold is changed by admin
    event NewLiquidationThreshold(
        VToken vToken,
        uint256 oldLiquidationThresholdMantissa,
        uint256 newLiquidationThresholdMantissa
    );

    /// @notice Emitted when liquidation incentive is changed by admin
    event NewLiquidationIncentive(uint256 oldLiquidationIncentiveMantissa, uint256 newLiquidationIncentiveMantissa);

    /// @notice Emitted when the liquidation incentive of a single market is changed by admin
    event NewMarketLiquidationIncentive(
        address indexed vToken,
        uint256 oldLiquidationIncentiveMantissa,
        uint256 newLiquidationIncentiveMantissa
    );

    /// @notice Emitted when price oracle is changed
    event NewPriceOracle(ResilientOracleInterface oldPriceOracle, ResilientOracleInterface newPriceOracle);

    /// @notice Emitted when the deviation-bounded oracle is changed
    event NewDeviationBoundedOracle(IDeviationBoundedOracle oldBoundedOracle, IDeviationBoundedOracle newBoundedOracle);

    /// @notice Emitted when an action is paused on a market
    event ActionPausedMarket(VToken vToken, Action action, bool pauseState);

    /// @notice Emitted when borrow cap for a vToken is changed
    event NewBorrowCap(VToken indexed vToken, uint256 newBorrowCap);

    /// @notice Emitted when the collateral threshold (in USD) for non-batch liquidations is changed
    event NewMinLiquidatableCollateral(uint256 oldMinLiquidatableCollateral, uint256 newMinLiquidatableCollateral);

    /// @notice Emitted when supply cap for a vToken is changed
    event NewSupplyCap(VToken indexed vToken, uint256 newSupplyCap);

    /// @notice Emitted when a rewards distributor is added
    event NewRewardsDistributor(address indexed rewardsDistributor, address indexed rewardToken);

    /// @notice Emitted when a market is supported
    event MarketSupported(VToken vToken);

    /// @notice Emitted when forced liquidation is enabled or disabled for a market
    event IsForcedLiquidationEnabledUpdated(address indexed vToken, bool enable);

    /// @notice Emitted when a market is unlisted
    event MarketUnlisted(address indexed vToken);

    /// @notice Emitted when the borrowing or redeeming delegate rights are updated for an account
    event DelegateUpdated(address indexed approver, address indexed delegate, bool approved);

    /// @notice Emitted when a market's supply allowlist is enabled or disabled
    event SupplyAllowlistEnabledUpdated(address indexed vToken, bool enabled);

    /// @notice Emitted when an account is added to or removed from a market's supply allowlist
    event AllowedSupplierUpdated(address indexed vToken, address indexed supplier, bool allowed);

    /// @notice Emitted when the pool's liquidation allowlist is enabled or disabled
    event LiquidationAllowlistEnabledUpdated(bool enabled);

    /// @notice Emitted when an account is added to or removed from the pool's liquidation allowlist
    event AllowedLiquidatorUpdated(address indexed liquidator, bool allowed);

    /// @notice Thrown when the close factor is outside the bounds set by `MIN_CLOSE_FACTOR_MANTISSA` and
    ///   `MAX_CLOSE_FACTOR_MANTISSA`
    error InvalidCloseFactor();

    /// @notice Thrown when collateral factor exceeds the upper bound
    error InvalidCollateralFactor();

    /// @notice Thrown when the liquidation threshold is lower than the collateral factor or greater than 1
    error InvalidLiquidationThreshold();

    /// @notice Thrown when a liquidation incentive is low enough that a liquidator would seize less value than it
    ///   repaid: below `1e18 + protocolSeizeShareMantissa` for a single market, below
    ///   `MIN_POOL_LIQUIDATION_INCENTIVE_MANTISSA` for the pool-wide fallback
    error InvalidLiquidationIncentive();

    /// @notice Thrown when a market's liquidation threshold times its liquidation incentive would be 1 or more, from
    ///   which point a liquidation no longer reduces the account's shortfall
    error UnsafeLiquidationParams(uint256 liquidationThresholdMantissa, uint256 liquidationIncentiveMantissa);

    /// @notice Thrown when the action is only available to specific sender, but the real sender was different
    error UnexpectedSender(address expectedSender, address actualSender);

    /// @notice Thrown when the oracle returns an invalid price for some asset
    error PriceError(address vToken);

    /// @notice Thrown if VToken unexpectedly returned a nonzero error code while trying to get account snapshot
    error SnapshotError(address vToken, address user);

    /// @notice Thrown when the market is not listed
    error MarketNotListed(address market);

    /// @notice Thrown when a market has an unexpected comptroller
    error ComptrollerMismatch();

    /// @notice Thrown when user is not member of market
    error MarketNotCollateral(address vToken, address user);

    /// @notice Thrown when borrow action is not paused
    error BorrowActionNotPaused();

    /// @notice Thrown when mint action is not paused
    error MintActionNotPaused();

    /// @notice Thrown when redeem action is not paused
    error RedeemActionNotPaused();

    /// @notice Thrown when repay action is not paused
    error RepayActionNotPaused();

    /// @notice Thrown when seize action is not paused
    error SeizeActionNotPaused();

    /// @notice Thrown when exit market action is not paused
    error ExitMarketActionNotPaused();

    /// @notice Thrown when transfer action is not paused
    error TransferActionNotPaused();

    /// @notice Thrown when enter market action is not paused
    error EnterMarketActionNotPaused();

    /// @notice Thrown when liquidate action is not paused
    error LiquidateActionNotPaused();

    /// @notice Thrown when borrow cap is not zero
    error BorrowCapIsNotZero();

    /// @notice Thrown when supply cap is not zero
    error SupplyCapIsNotZero();

    /// @notice Thrown when collateral factor is not zero
    error CollateralFactorIsNotZero();

    /**
     * @notice Thrown during the liquidation if user's total collateral amount is lower than
     *   a predefined threshold. In this case only batch liquidations (either liquidateAccount
     *   or healAccount) are available.
     */
    error MinimalCollateralViolated(uint256 expectedGreaterThan, uint256 actual);

    /**
     * @notice Thrown by the batch operations when the account's total collateral is above
     *   `minLiquidatableCollateral`, which means it is large enough for a regular `VToken.liquidateBorrow`
     * @dev Same name, arguments and meaning as the shared `Comptroller`, so a decoder written against either one
     *   reads this correctly.
     */
    error CollateralExceedsThreshold(uint256 expectedLessThanOrEqualTo, uint256 actual);

    /// @notice Thrown by `healAccount` when the collateral can clear the whole debt at each market's own liquidation
    ///   incentive, so healing would forgive nothing and `liquidateAccount` has to be used instead
    error CollateralCoversDebt(uint256 borrows, uint256 maxClearableDebt);

    /// @notice Thrown by `liquidateAccount` when the debt is too large for the collateral to clear, so `healAccount`
    ///   has to be used instead. Reports the debt and the largest debt the collateral could have cleared.
    /// @dev Deliberately not the shared `Comptroller`'s `InsufficientCollateral`: both arguments here are debt values
    ///   rather than collateral values, and reusing that name would leave the two versions sharing one selector.
    error DebtExceedsClearableAmount(uint256 borrows, uint256 maxClearableDebt);

    /// @notice Thrown when the account doesn't have enough liquidity to redeem or borrow
    error InsufficientLiquidity();

    /// @notice Thrown when trying to liquidate a healthy account
    error InsufficientShortfall();

    /// @notice Thrown if the liquidation allowlist is enabled and the account liquidating is not on it
    error LiquidationNotAllowed(address liquidator);

    /// @notice Thrown when trying to repay more than allowed by close factor
    error TooMuchRepay();

    /// @notice Thrown if the user is trying to exit a market in which they have an outstanding debt
    error NonzeroBorrowBalance();

    /// @notice Thrown if a debt remains in any of the borrower's markets once every liquidation order has been
    ///   executed, which means the orders passed to `liquidateAccount` did not cover the whole position
    error NonzeroBorrowBalanceAfterLiquidation();

    /// @notice Thrown when trying to perform an action that is paused
    error ActionPaused(address market, Action action);

    /// @notice Thrown when trying to add a market that is already listed
    error MarketAlreadyListed(address market);

    /// @notice Thrown when the market being listed does not identify itself as a VToken
    error InvalidVToken();

    /// @notice Thrown when an array argument is empty, or when two array arguments have different lengths
    error InvalidArrayLength();

    /// @notice Thrown if the supply cap is exceeded
    error SupplyCapExceeded(address market, uint256 cap);

    /// @notice Thrown if the account being credited with the minted vTokens is not on the market's supply allowlist
    error SupplyNotAllowed(address market, address supplier);

    /// @notice Thrown if the borrow cap is exceeded
    error BorrowCapExceeded(address market, uint256 cap);

    /// @notice Thrown if delegate approval status is already set to the requested value
    error DelegationStatusUnchanged();

    /// @notice Thrown when adding a rewards distributor that this pool already has
    error RewardsDistributorAlreadyExists();
}

/**
 * @title SpokeComptrollerViewInterface
 * @author Venus
 * @notice The getters `SpokeComptroller` adds on top of the pooled `Comptroller`, for integrators that read this pool
 * rather than implement it - the Liquidity Hub's spoke adapter, lenses, keepers and VIP tooling.
 * @dev Standalone and not implemented by `SpokeComptroller`, matching how `ComptrollerViewInterface` exposes the
 * shared pool's getters.
 *
 * Scope is the supply side: what an integrator that funds this pool has to read before and while it supplies, plus
 * the two allowlists and the per-market discount that only exist on this fork. `supplyCaps` and `actionPaused` are
 * repeated from `ComptrollerViewInterface` and `ComptrollerInterface` rather than inherited, so that a consumer of a
 * spoke pool needs one import and not three. `actionPaused` also has to be repeated on its own terms: the shared
 * declaration types its second argument as the `Action` enum, and a consumer that does not want this repo's enum in
 * its build needs the ABI-equivalent `uint8` form. The two share a selector, so they cannot both be declared in one
 * inheritance chain - which is the reason this interface inherits nothing.
 *
 * `markets` is repeated for a different reason: the shared declaration returns two of the three words the getter
 * actually produces, so a consumer reading it there silently loses `liquidationThresholdMantissa`. The form declared
 * here returns all three.
 *
 * Anything else the fork shares with the pooled `Comptroller` - `borrowCaps`, `oracle`, `closeFactorMantissa`,
 * `minLiquidatableCollateral` - is read through `ComptrollerViewInterface` as usual.
 */
interface SpokeComptrollerViewInterface {
    /**
     * @notice The listing state and both collateral weights of a market
     * @dev The auto-generated getter over the `markets` mapping. It returns three words, one per non-mapping member
     *   of `Market`. `ComptrollerViewInterface` declares only the first two, so a caller reading the getter through
     *   that declaration drops `liquidationThresholdMantissa` without any error: the extra word is simply trailing
     *   return data the decoder ignores. Read it here to get all three.
     * @param vToken The market to query
     * @return isListed True once the market has been added to the pool
     * @return collateralFactorMantissa The most an account may borrow against this collateral, scaled by 1e18
     * @return liquidationThresholdMantissa The weighting past which the position becomes liquidatable, scaled by 1e18
     */
    function markets(
        address vToken
    ) external view returns (bool isListed, uint256 collateralFactorMantissa, uint256 liquidationThresholdMantissa);

    /**
     * @notice Whether a market may be liquidated while the borrower is still above the liquidation threshold
     * @dev Read in `preLiquidateHook`. While this is set the close factor no longer bounds the repayment, so a
     *   position in the market can be closed in full in one call.
     * @param vToken The market to read the setting of
     * @return enabled True if this market allows liquidation without a shortfall
     */
    function isForcedLiquidationEnabled(address vToken) external view returns (bool enabled);

    /**
     * @notice The most underlying a market will hold before it stops accepting supply
     * @dev `type(uint256).max` disables the check. Zero is a real cap of zero rather than an "unset" sentinel:
     *   `preMintHook` compares `nextTotalSupply > supplyCap`, so a market left at zero rejects every mint.
     * @param vToken The market to query
     * @return cap The market's supply cap, in underlying units
     */
    function supplyCaps(address vToken) external view returns (uint256 cap);

    /**
     * @notice Whether a market accepts supply only from the accounts on its supply allowlist
     * @dev Enforced in `preMintHook` alone. Redeeming is never restricted, and a market that has never had this
     *   enabled accepts supply from anyone.
     * @param vToken The market to read the setting of
     * @return enabled True if the market's supply allowlist is armed
     */
    function isSupplyAllowlistEnabled(address vToken) external view returns (bool enabled);

    /**
     * @notice Whether an account may supply to a market while that market's supply allowlist is enabled
     * @dev The account this meters is the one CREDITED with the newly minted vTokens, not the one paying for them:
     *   `mintBehalf` lets a third party fund a mint attributed to someone else, and metering the recipient is what
     *   bounds the market's supply.
     * @param vToken The market whose allowlist to read
     * @param supplier The account to test
     * @return allowed True if `supplier` may be credited with this market's vTokens
     */
    function isAllowedSupplier(address vToken, address supplier) external view returns (bool allowed);

    /**
     * @notice Whether seizing collateral in this pool is restricted to the accounts on the liquidation allowlist
     * @dev Pool-wide rather than per market, because `healAccount` seizes across every market the borrower is in and
     *   so cannot attribute a seizure to a single one of them.
     * @return enabled True if the pool's liquidation allowlist is armed
     */
    function isLiquidationAllowlistEnabled() external view returns (bool enabled);

    /**
     * @notice Whether an account may seize collateral in this pool while the liquidation allowlist is enabled
     * @param liquidator The account to test
     * @return allowed True if `liquidator` may seize collateral in this pool
     */
    function isAllowedLiquidator(address liquidator) external view returns (bool allowed);

    /**
     * @notice The discount a market has of its own, or zero when it takes the pool-wide one
     * @dev Zero is the "unset" sentinel rather than a real discount. Read `effectiveLiquidationIncentive` to get the
     *   value that actually applies to a market.
     * @param vToken The collateral market to read the discount of
     * @return incentiveMantissa The market's own discount scaled by 1e18, or zero if it has none
     */
    function liquidationIncentives(address vToken) external view returns (uint256 incentiveMantissa);

    /**
     * @notice The discount that applies to a market: its own if it has one, otherwise the pool-wide value
     * @param vToken The collateral market to read the discount of
     * @return incentiveMantissa The discount that prices this market's collateral, scaled by 1e18
     */
    function effectiveLiquidationIncentive(address vToken) external view returns (uint256 incentiveMantissa);

    /**
     * @notice The oracle that bounds an asset's price against a recent window
     * @dev Read only where the collateral factor weights a position. The liquidation-threshold paths stay on the
     *   `oracle`, because they route liquidations. Zero until governance sets it, and while it is zero borrowing and
     *   redeeming fail closed.
     * @return boundedOracle The deviation-bounded oracle this pool prices borrowing capacity through
     */
    function deviationBoundedOracle() external view returns (IDeviationBoundedOracle boundedOracle);

    /**
     * @notice Whether an action is paused on a market
     * @dev Typed as `uint8` rather than `Action` so that a consumer can read this without importing the enum. The
     *   encoding is identical; the deployed ordering is
     *   `{ MINT, REDEEM, BORROW, REPAY, SEIZE, LIQUIDATE, TRANSFER, ENTER_MARKET, EXIT_MARKET }`.
     * @param market The market to query
     * @param action The action, as its position in `Action`
     * @return paused True if the action is paused on this market
     */
    function actionPaused(address market, uint8 action) external view returns (bool paused);
}

contracts/Spoke/SpokeComptrollerStorage..content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { IDeviationBoundedOracle } from "@venusprotocol/oracle/contracts/interfaces/IDeviationBoundedOracle.sol";

import { VToken } from "../VToken.sol";
import { RewardsDistributor } from "../Rewards/RewardsDistributor.sol";
import { Action } from "../ComptrollerInterface.sol";

/**
 * @title SpokeComptrollerStorage
 * @author Venus
 * @notice Storage layout for the `SpokeComptroller` contract.
 * @dev Fork of `ComptrollerStorage` (`contracts/ComptrollerStorage.sol`), kept separate so the spoke layout and the
 * `AccountLiquiditySnapshot` struct can change without touching the shared implementation. Re-synced by hand when
 * `ComptrollerStorage` changes, like the implementation it accompanies.
 */
contract SpokeComptrollerStorage {
    struct LiquidationOrder {
        VToken vTokenCollateral;
        VToken vTokenBorrowed;
        uint256 repayAmount;
    }

    /// @dev `totalCollateral` and `maxClearableDebt` are only meaningful under
    /// `WeightFunction.USE_LIQUIDATION_THRESHOLD`, which is the weighting every caller that reads them passes. Under
    /// the collateral factor `totalCollateral` is derived from the deviation-bounded collateral price rather than spot,
    /// and `maxClearableDebt` is not accumulated at all, so it stays at zero. A new caller on that weighting must not
    /// start reading either one without deciding what it wants first: a zero `maxClearableDebt` puts `healAccount` on a
    /// repayment percentage of zero, which forgives the whole position as bad debt.
    struct AccountLiquiditySnapshot {
        uint256 totalCollateral;
        uint256 weightedCollateral;
        uint256 borrows;
        uint256 effects;
        uint256 liquidity;
        uint256 shortfall;
        // The largest borrow value the account's collateral can clear without leaving bad debt behind, computed as
        // the sum over the account's collateral markets of `collateralValue / liquidationIncentive`, each market at
        // its own incentive. Used to route an under-threshold account between `liquidateAccount` and `healAccount`.
        uint256 maxClearableDebt;
    }

    struct RewardSpeeds {
        address rewardToken;
        uint256 supplySpeed;
        uint256 borrowSpeed;
    }

    struct Market {
        // Whether or not this market is listed
        bool isListed;
        //  Multiplier representing the most one can borrow against their collateral in this market.
        //  For instance, 0.9 to allow borrowing 90% of collateral value.
        //  Must be at most `MAX_COLLATERAL_FACTOR_MANTISSA`, stored as a mantissa.
        uint256 collateralFactorMantissa;
        //  Multiplier representing the collateralization after which the borrow is eligible
        //  for liquidation. For instance, 0.8 liquidate when the borrow is 80% of collateral
        //  value. Must be between the collateral factor and 1, stored as a mantissa.
        uint256 liquidationThresholdMantissa;
        // Per-market mapping of "accounts in this asset"
        mapping(address => bool) accountMembership;
    }

    /**
     * @notice Oracle which gives the price of any given asset
     */
    ResilientOracleInterface public oracle;

    /**
     * @notice Multiplier used to calculate the maximum repayAmount when liquidating a borrow
     */
    uint256 public closeFactorMantissa;

    /**
     * @notice Multiplier representing the discount on collateral that a liquidator receives, applied to every market
     * that has no discount of its own
     * @dev Internal rather than public, because the `liquidationIncentiveMantissa()` getter has to resolve the
     * caller's market before answering: `VToken` reads that getter on itself and needs the discount that prices its
     * own collateral, not the pool-wide default. See `SpokeComptroller.liquidationIncentiveMantissa`.
     */
    uint256 internal _poolLiquidationIncentiveMantissa;

    /**
     * @notice Per-account mapping of "assets you are in"
     */
    mapping(address => VToken[]) public accountAssets;

    /**
     * @notice Official mapping of vTokens -> Market metadata
     * @dev Used e.g. to determine if a market is supported
     */
    mapping(address => Market) public markets;

    /// @notice A list of all markets
    VToken[] public allMarkets;

    /// @notice Borrow caps enforced by borrowAllowed for each vToken address. Defaults to zero which restricts borrowing.
    mapping(address => uint256) public borrowCaps;

    /// @notice Minimal collateral required for regular (non-batch) liquidations
    uint256 public minLiquidatableCollateral;

    /// @notice Supply caps enforced by mintAllowed for each vToken address. Defaults to zero which corresponds to minting not allowed
    mapping(address => uint256) public supplyCaps;

    /// @notice True if a certain action is paused on a certain market
    mapping(address => mapping(Action => bool)) internal _actionPaused;

    // List of Reward Distributors added
    RewardsDistributor[] internal rewardsDistributors;

    // Used to check if rewards distributor is added
    mapping(address => bool) internal rewardsDistributorExists;

    /// @notice Flag indicating whether forced liquidation enabled for a market
    mapping(address => bool) public isForcedLiquidationEnabled;

    uint256 internal constant NO_ERROR = 0;

    // closeFactorMantissa must be strictly greater than this value
    uint256 internal constant MIN_CLOSE_FACTOR_MANTISSA = 0.05e18; // 0.05

    // closeFactorMantissa must not exceed this value
    uint256 internal constant MAX_CLOSE_FACTOR_MANTISSA = 0.9e18; // 0.9

    // No collateralFactorMantissa may exceed this value
    uint256 internal constant MAX_COLLATERAL_FACTOR_MANTISSA = 0.95e18; // 0.95

    // No pool-wide liquidation incentive may fall below this value. It is `1e18 + VToken`'s
    // `DEFAULT_PROTOCOL_SEIZE_SHARE_MANTISSA`, restated here because that constant is internal to `VToken` and a
    // market's share is only readable once the market exists. A newly listed market carries the default share and no
    // incentive of its own, so this floor is what keeps its first liquidation from paying the liquidator less than it
    // repaid. It is a backstop for that case, not a full guarantee: a market whose share is later raised above the
    // default needs an incentive of its own, which `setMarketLiquidationIncentive` and `VToken.setProtocolSeizeShare`
    // bound from both sides.
    uint256 internal constant MIN_POOL_LIQUIDATION_INCENTIVE_MANTISSA = 1.05e18; // 1e18 + 0.05e18

    /// @notice Whether the delegate is allowed to borrow or redeem on behalf of the user
    //mapping(address user => mapping (address delegate => bool approved)) public approvedDelegates;
    mapping(address => mapping(address => bool)) public approvedDelegates;

    /// @notice Whether a market accepts supply only from the accounts on its supply allowlist. Keyed by market, and
    /// disabled by default, so a newly listed market accepts supply from anyone.
    mapping(address => bool) public isSupplyAllowlistEnabled;

    /// @notice The accounts a market accepts supply from while its supply allowlist is enabled. Keyed by market,
    /// then by account.
    mapping(address => mapping(address => bool)) public isAllowedSupplier;

    /// @notice Whether seizing collateral in this pool is restricted to the accounts on the liquidation allowlist.
    /// Disabled by default.
    /// @dev Pool-wide rather than per market, because `healAccount` seizes across every market the borrower is in and
    /// so cannot attribute a seizure to a single one of them.
    bool public isLiquidationAllowlistEnabled;

    /// @notice The accounts allowed to seize collateral in this pool while the liquidation allowlist is enabled
    mapping(address => bool) public isAllowedLiquidator;

    /// @notice Per-market discount a liquidator receives on the collateral it seizes, scaled by 1e18. Keyed by the
    /// collateral market, since that is what the discount prices.
    /// @dev Zero means no market value has been set, in which case `_poolLiquidationIncentiveMantissa` applies. That
    /// pool-wide value is always at least 1e18 for a listed market: `PoolRegistry.addMarket` refuses to add one to an
    /// unregistered pool, and registering a pool goes through `setLiquidationIncentive`, which enforces the floor.
    mapping(address => uint256) public liquidationIncentives;

    /// @notice Oracle that bounds an asset's price against a recent window, so a deviating print cannot inflate
    /// borrowing capacity. Read only where the collateral factor weights the position; the liquidation-threshold
    /// paths stay on `oracle`, because they route liquidations.
    IDeviationBoundedOracle public deviationBoundedOracle;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     * The size is derived from the 47 slots `ComptrollerStorage` reserves: plus one for the Prime token slot, which
     * is unused here and is returned to the gap rather than left as a hole, minus the six slots the allowlists, the
     * per-market liquidation incentives and the deviation-bounded oracle above take. This contract therefore occupies
     * the same number of slots as the one it was forked from.
     *
     * That is not layout compatibility. Reclaiming the Prime slot moved every variable declared after it up by one,
     * so `approvedDelegates` here sits in the slot `ComptrollerStorage` gives to `prime`, and the two layouts cannot
     * be swapped under a live pool in either direction. They do not have to be: a spoke pool upgrades through its own
     * beacon. `tests/hardhat/Spoke/storageLayout.ts` pins the slot list, the divergence and this gap size.
     */
    uint256[42] private __gap;
}

contracts/test/HubSpoke/AdapterSpokeV1.s.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { IResourceAdapter } from "./interfaces/IResourceAdapter.sol";
import { IVTokenIsolated } from "./interfaces/external/IVTokenIsolated.sol";
import { ISpokeComptroller } from "./interfaces/external/ISpokeComptroller.sol";

/**
 * @title AdapterSpokeV1
 * @author Venus
 * @notice Stateless adapter for the liquidity side of a hub-funded spoke pool — an isolated-pools
 *         `VToken` governed by a `SpokeComptroller`. ONE deployment serves every YieldGroup that
 *         registers a spoke market; there is no per-(YieldGroup, market) instance, no proxy, no
 *         clone factory.
 * @dev Dispatch model: mutating functions (`deposit`, `withdraw`) MUST be invoked via DELEGATECALL
 *      from a YieldGroup. They execute in the YieldGroup's storage context, so vTokens are credited
 *      to / burned from the YieldGroup, not this adapter. View functions are invoked via normal
 *      CALL / STATICCALL; those that name a `holder` read the position from that argument, while
 *      {maxDeposit} and {validateRegistration} read `msg.sender` instead (see below).
 *
 *      Storage-safety invariants enforced by this contract:
 *      1. Zero `internal`/`private`/`public` state variables are declared. Only `immutable` values
 *         are used. Immutables live in bytecode, not storage slots, so they're delegatecall-safe.
 *      2. No inline assembly performs `sstore`.
 *      3. All external calls go to the supplied `resource` (vToken), its `underlying()`, or its
 *         `comptroller()`. No arbitrary user-supplied call target.
 *      4. {onlyDelegateCall} reverts when a mutating function is invoked directly on the adapter,
 *         preventing accidents that would orphan vTokens here.
 *
 *      **Written-off debt stays in the mark.** {totalAssets} values the position at the market's own
 *      exchange rate, as `AdapterCoreV1` does. That rate keeps `badDebt` in its numerator, so a
 *      write-off in `healAccount` does not lower it. The written-off amount is not cash, so the
 *      market cannot pay every supplier in full until its `shortfall` calls `badDebtRecovered`,
 *      which lowers `badDebt` and raises cash by the same amount without moving the rate. Until
 *      then, suppliers who exit first are paid at the full rate out of the cash that remains, and
 *      {maxWithdraw} is bounded by that cash.
 *
 *      **Why this is not `AdapterCoreV1`.** The two speak nearly the same selectors and disagree on
 *      the numbers below. Four differences, each verified against `isolated-pools`:
 *
 *      - **Liquidity is cash NET of reserves**, and both it and the position are floored to a whole
 *        number of vTokens, because {withdraw} redeems by vToken COUNT rather than by underlying
 *        amount. Naming the burn instead of letting `redeemUnderlying` derive it is what keeps a
 *        certified amount inside the position's own balance: the derived burn rounds UP and is
 *        subtracted in checked arithmetic, so an amount one unit too large panics rather than
 *        failing gracefully.
 *      - **No exit fee to gross up.** Isolated pools have no `treasuryPercent`; their cut is the
 *        reserve factor, already netted out of the exchange rate. There is nothing unmodeled to
 *        reject at registration, so {validateRegistration} guards the market listing and the supply
 *        allowlist instead.
 *      - **The supply cap has an uncapped sentinel**, `type(uint256).max` (see
 *        {ISpokeComptroller-supplyCaps}).
 *      - **Mutating calls carry no error code to check.** `mint`, `redeem` and `accrueInterest`
 *        return `NO_ERROR` or revert; the Compound-style codes `AdapterCoreV1` inspects are set by
 *        the legacy Core pool alone.
 *
 *      **The supply allowlist and caller identity.** A spoke market can restrict minting to
 *      allowlisted accounts, and the account it checks is the one CREDITED with the vTokens. Under
 *      delegatecall that is the YieldGroup. {maxDeposit} and {validateRegistration} take no `holder`,
 *      and both are invoked by the YieldGroup as a plain call, so `msg.sender` IS the prospective
 *      supplier and reading the allowlist against it is exact rather than a convention. This matters
 *      operationally: a YieldGroup whose grant is revoked reports zero room and is routed around,
 *      instead of advertising capacity that every deposit then reverts on.
 *
 *      Fee-on-transfer underlyings are unsupported, matching the Hub. The market itself tolerates
 *      them (it mints against the measured delta) but {deposit} reports the requested amount, so the
 *      YieldGroup's accounting would drift.
 */
contract AdapterSpokeV1 is IResourceAdapter {
    using SafeERC20 for IERC20;

    // ============================== State (immutable only) ====================

    /// @notice This adapter's own address, captured at deployment. Used by {onlyDelegateCall} to
    ///         detect direct invocation. Immutables live in bytecode, not storage.
    address private immutable _ADAPTER_SELF;

    // ============================== State (constants) =========================

    /// @notice Fixed-point scale matching Compound's mantissa (`1e18`).
    uint256 public constant EXP_SCALE = 1e18;

    /// @notice Deposit room reported for a market whose supply cap is the isolated-pools "uncapped"
    ///         sentinel (`type(uint256).max`).
    /// @dev Finite on purpose. `YieldGroupBase.maxDeposit()` SUMS the room of every queued resource
    ///      in checked arithmetic, so reporting `type(uint256).max` would overflow that sum the
    ///      moment a second uncapped market joined the queue — the YieldGroup's whole capacity view
    ///      would revert and the Hub would read it as zero capacity with an immovable balance. At
    ///      `2^128 - 1` the sum cannot overflow for any realistic queue, while the value is still
    ///      unreachable for any real token (~3.4e20 whole units at 18 decimals). Mirrors the Flux
    ///      family, where Fluid reports `int128.max` for the same reason. The binding controls on an
    ///      uncapped market are the YieldGroup's per-resource cap and the Hub's dual cap, not this.
    uint256 public constant UNCAPPED_DEPOSIT_ROOM = type(uint128).max;

    /// @notice Scaling factor between mantissa-rate (`1e18`) and BPS (`1e4`).
    uint256 internal constant MANTISSA_TO_BPS = 1e14;

    /// @notice `Action.MINT` in the isolated-pools Comptroller enum.
    uint8 internal constant ACTION_MINT = 0;

    /// @notice `Action.REDEEM` in the isolated-pools Comptroller enum.
    uint8 internal constant ACTION_REDEEM = 1;

    /// @notice Fraction of raw supply-cap headroom withheld to absorb interest accrued between a
    ///         `maxDeposit` read and the mint it sizes (`1/1000` = 0.1%).
    uint256 internal constant CAP_TRIM_DIVISOR = 1000;

    // ============================== Errors ===================================

    /// @notice A mutating function was invoked directly (not via delegatecall).
    error NotDelegateCall();

    /**
     * @notice A redeem succeeded but delivered less than the requested amount. Indicates a
     *         fee-on-transfer underlying or a market bug — an isolated-pools redeem otherwise
     *         delivers at least what was asked for.
     * @param resource Resource that under-delivered.
     * @param requested Underlying units expected.
     * @param actual Underlying units actually received.
     */
    error VTokenUnderfilled(address resource, uint256 requested, uint256 actual);

    /**
     * @notice The deposit is too small to mint a single vToken, so the market would keep the
     *         underlying and issue nothing for it.
     * @dev Reverting hands the leg back to the YieldGroup's deposit cascade, which routes around it;
     *      minting zero would strand the amount silently. Reachable when the Hub cascade leaves this
     *      market a remainder under one vToken unit (about 1e10 wei for an 18-decimal underlying).
     * @param resource Market that would have minted zero.
     * @param amount Underlying units offered.
     * @param minimum Underlying units needed to mint one vToken.
     */
    error DepositBelowOneVToken(address resource, uint256 amount, uint256 minimum);

    /**
     * @notice The market's supply allowlist is enabled and the prospective supplier is not on it.
     * @param resource Market whose allowlist rejected the supplier.
     * @param supplier Account that would be credited with the vTokens (the YieldGroup).
     */
    error SupplyNotAllowed(address resource, address supplier);

    /**
     * @notice The market is not listed by the Comptroller it names, so it can never be minted.
     * @param resource Market that its own Comptroller does not list.
     */
    error MarketNotListed(address resource);

    // ============================== Modifiers ================================

    /// @notice Reverts {NotDelegateCall} when the call is not arriving via delegatecall.
    /// @dev During a delegatecall, `address(this)` is the caller's address; during a direct call it
    ///      equals `_ADAPTER_SELF` (the address captured at construction).
    modifier onlyDelegateCall() {
        if (address(this) == _ADAPTER_SELF) revert NotDelegateCall();
        _;
    }

    // ============================== Constructor ==============================

    /// @notice Captures the adapter's own address into an immutable for {onlyDelegateCall}.
    constructor() {
        _ADAPTER_SELF = address(this);
    }

    // ============================== External — mutating =======================

    /// @inheritdoc IResourceAdapter
    /// @dev `address(this)` here is the YieldGroup (delegatecall context), which already holds
    ///      `amount` of underlying. We approve the market and mint; delegatecall preserves the caller
    ///      context, so the market sees the YieldGroup as `msg.sender` and credits the vTokens there.
    ///      That is also the account its supply allowlist checks.
    function deposit(address resource, uint256 amount) external override onlyDelegateCall returns (uint256 deposited) {
        uint256 minimum = _oneVTokenUnit(IVTokenIsolated(resource).exchangeRateStored());
        if (amount < minimum) revert DepositBelowOneVToken(resource, amount, minimum);

        IERC20 assetToken = IERC20(IVTokenIsolated(resource).underlying());
        assetToken.forceApprove(resource, amount);
        IVTokenIsolated(resource).mint(amount);
        return amount;
    }

    /// @inheritdoc IResourceAdapter
    /// @dev `address(this)` here is the YieldGroup, so the redeem burns its vTokens and credits the
    ///      underlying back to it.
    ///
    ///      Denominated in vTokens, not in underlying. `redeemUnderlying` DERIVES the burn from the
    ///      request by rounding up, and that derived count is not bounded by the caller's balance —
    ///      `_redeemFresh` subtracts it in checked arithmetic and panics when it overshoots. Naming
    ///      the burn removes the derivation: {_burnFor} is the fewest vTokens worth at least
    ///      `amount`, and {maxWithdraw} certifies nothing the position cannot cover that many times
    ///      over.
    ///
    ///      The payout is `truncate(exchangeRate x tokens)`, so it is `>= amount` and exceeds it by
    ///      up to one vToken unit. We forward exactly `amount` and leave the surplus as idle on the
    ///      YieldGroup, where `totalAssets` counts it and the next withdrawal consumes it
    ///      idle-first — the same treatment `AdapterCoreV1` gives its gross-up surplus, and what
    ///      keeps the YieldGroup's `received == requested` invariant true.
    function withdraw(address resource, uint256 amount, address to) external override onlyDelegateCall {
        IERC20 assetToken = IERC20(IVTokenIsolated(resource).underlying());

        uint256 exchangeRate = IVTokenIsolated(resource).exchangeRateStored();
        uint256 preBal = assetToken.balanceOf(address(this));
        IVTokenIsolated(resource).redeem(_burnFor(exchangeRate, amount));
        uint256 received = assetToken.balanceOf(address(this)) - preBal;
        if (received < amount) revert VTokenUnderfilled(resource, amount, received);

        assetToken.safeTransfer(to, amount);
    }

    /// @inheritdoc IResourceAdapter
    /// @dev Plain CALL, no `onlyDelegateCall`: `accrueInterest` mutates the market's own global
    ///      index, not this caller's position, so it is safe (and cheaper) to run in the adapter's
    ///      context. After it returns, every view below is fresh to the current block or timestamp.
    function accrue(address resource) external override {
        IVTokenIsolated(resource).accrueInterest();
    }

    // ============================== External — view ==========================

    /// @inheritdoc IResourceAdapter
    function asset(address resource) external view override returns (address) {
        return IVTokenIsolated(resource).underlying();
    }

    /// @inheritdoc IResourceAdapter
    /// @dev `balance x exchangeRateStored`: the market's own valuation of the tokens, and what
    ///      redeeming all of them would pay at the stored rate if the market had the cash. Includes
    ///      the position's share of `badDebt`; see the contract NatSpec.
    function totalAssets(address resource, address holder) external view override returns (uint256) {
        uint256 vBal = IVTokenIsolated(resource).balanceOf(holder);
        if (vBal == 0) return 0;
        return (vBal * IVTokenIsolated(resource).exchangeRateStored()) / EXP_SCALE;
    }

    /// @inheritdoc IResourceAdapter
    /// @dev Honors, in order: the market's supply allowlist (against `msg.sender`, the prospective
    ///      supplier — see the contract NatSpec), its MINT pause, and its supply cap. The headroom
    ///      math mirrors `preMintHook`'s `nextTotalSupply = totalSupply x exchangeRate + mintAmount`
    ///      check. Room below one vToken unit is reported as zero, because a deposit of it would
    ///      mint nothing.
    function maxDeposit(address resource) external view override returns (uint256) {
        ISpokeComptroller comptrollerContract = ISpokeComptroller(IVTokenIsolated(resource).comptroller());
        if (
            comptrollerContract.isSupplyAllowlistEnabled(resource) &&
            !comptrollerContract.isAllowedSupplier(resource, msg.sender)
        ) {
            return 0;
        }
        if (comptrollerContract.actionPaused(resource, ACTION_MINT)) return 0;

        uint256 supplyCap = comptrollerContract.supplyCaps(resource);
        // A cap of zero is a real cap here, not an "unset" sentinel: `preMintHook` rejects every
        // non-zero mint against it. The uncapped sentinel is `type(uint256).max`.
        if (supplyCap == 0) return 0;
        if (supplyCap == type(uint256).max) return UNCAPPED_DEPOSIT_ROOM;

        uint256 exchangeRate = IVTokenIsolated(resource).exchangeRateStored();
        uint256 supplied = (IVTokenIsolated(resource).totalSupply() * exchangeRate) / EXP_SCALE;
        if (supplied >= supplyCap) return 0;

        uint256 room = supplyCap - supplied;
        // `exchangeRateStored` is pre-accrual, but the market re-checks the cap at mint AFTER
        // `accrueInterest` raises the rate, so the raw headroom is slightly optimistic on an
        // interest-accruing near-cap market. Withhold a small conservative margin so a normal accrual
        // between this view and execution cannot push `deposit(maxDeposit())` over the cap. The
        // routing cascade is the backstop for larger staleness (an over-cap leg is skipped, not
        // bubbled), so this only needs to absorb a typical inter-slot accrual.
        room -= room / CAP_TRIM_DIVISOR;
        return room < _oneVTokenUnit(exchangeRate) ? 0 : room;
    }

    /// @inheritdoc IResourceAdapter
    /// @dev Two constraints: the position's value, and the market's payable cash
    ///      (`getCash - totalReserves` — reserves sit inside cash but are not redeemable, and
    ///      `_redeemFresh` gates on the difference). Subtracting reserves also makes this figure
    ///      invariant across the reserve sweep `accrueInterest` performs, which lowers cash and
    ///      reserves by the same amount.
    ///
    ///      Both are expressed as a whole number of vTokens and valued back into underlying, because
    ///      {withdraw} redeems by count: an amount at or below `truncate(exchangeRate x t)` is
    ///      coverable by `t` tokens, so flooring at `t` is what makes the bound executable rather
    ///      than merely arithmetically true. The position side is `truncate(exchangeRate x vBal)`,
    ///      already floored at the tokens held; the cash side is floored to the tokens the market
    ///      can pay for. Flooring is exact rather than conservative — no margin is withheld — so the
    ///      last vToken stays withdrawable, which is what lets a market be drained to zero and
    ///      deregistered.
    ///
    ///      Reads stored state, so the figure is exact only for a caller that has already settled
    ///      this market's interest in the same transaction — the Hub's routing paths all do, via
    ///      {accrue}. Against an unaccrued market it is optimistic by the reserves the next accrual
    ///      will book, since those come out of the payable cash.
    function maxWithdraw(address resource, address holder) external view override returns (uint256) {
        ISpokeComptroller comptrollerContract = ISpokeComptroller(IVTokenIsolated(resource).comptroller());
        if (comptrollerContract.actionPaused(resource, ACTION_REDEEM)) return 0;

        uint256 vBal = IVTokenIsolated(resource).balanceOf(holder);
        if (vBal == 0) return 0;

        uint256 exchangeRate = IVTokenIsolated(resource).exchangeRateStored();
        if (exchangeRate == 0) return 0;

        uint256 ourValue = (vBal * exchangeRate) / EXP_SCALE;
        if (ourValue == 0) return 0;

        uint256 cash = IVTokenIsolated(resource).getCash();
        uint256 reserves = IVTokenIsolated(resource).totalReserves();
        if (cash <= reserves) return 0;

        uint256 payableTokens = ((cash - reserves) * EXP_SCALE) / exchangeRate;
        uint256 cashBound = (payableTokens * exchangeRate) / EXP_SCALE;

        return ourValue < cashBound ? ourValue : cashBound;
    }

    /// @inheritdoc IResourceAdapter
    /// @dev The `blocksPerYear` parameter is IGNORED. An isolated-pools market carries its own
    ///      annualiser as an immutable and can be block-based or time-based, so a YieldGroup-level
    ///      constant would misprice whichever kind it was not configured for; the market's own value
    ///      always matches the unit of its own rate. Deploy the spoke YieldGroup with
    ///      `blocksPerYear = 0`, as the Flux family already does.
    ///
    ///      An emptied market reports 0 rather than reverting: `JumpRateModelV2.getSupplyRate`
    ///      divides by `cash + borrows + badDebt - reserves` with no zero guard. `PoolLens` guards
    ///      the same read.
    function spotAPYBps(address resource, uint256 /* blocksPerYear */) external view override returns (uint64) {
        if (IVTokenIsolated(resource).totalSupply() == 0) return 0;

        uint256 annualised = (IVTokenIsolated(resource).supplyRatePerBlock() *
            IVTokenIsolated(resource).blocksOrSecondsPerYear()) / MANTISSA_TO_BPS;
        // forge-lint: disable-next-line(unsafe-typecast)
        return annualised > type(uint64).max ? type(uint64).max : uint64(annualised);
    }

    /// @inheritdoc IResourceAdapter
    function receiptBalance(address resource, address holder) external view override returns (uint256) {
        return IVTokenIsolated(resource).balanceOf(holder);
    }

    /// @inheritdoc IResourceAdapter
    function resourceName(address resource) external view override returns (string memory) {
        return IERC20Metadata(resource).name();
    }

    /// @inheritdoc IResourceAdapter
    /// @dev Rejects the two configurations `preMintHook` would reject on every deposit, either of
    ///      which would leave the resource holding a queue slot it can never fill: a market its own
    ///      Comptroller does not list, and a market whose supply allowlist is enabled without the
    ///      registering YieldGroup on it. `msg.sender` is the YieldGroup (see the contract NatSpec),
    ///      which is the account the market's allowlist gates.
    ///
    ///      The listing check is also what ties `resource` to the Comptroller it names: any contract
    ///      can return a real `SpokeComptroller` from `comptroller()`, but only a market that
    ///      Comptroller actually lists passes here. The allowlist accessors then pin the Comptroller
    ///      to the spoke fork, since they exist nowhere else and the call reverts against any other
    ///      Comptroller. Nothing else is asserted. In particular an unset `deviationBoundedOracle`
    ///      is NOT grounds for rejection: it blocks borrowing, and so the market's yield, but leaves
    ///      the Hub's own paths intact — `preMintHook` never reads a price, and `preRedeemHook`
    ///      returns before the priced liquidity check for an account that is not a market member,
    ///      which a supply-only YieldGroup never becomes.
    function validateRegistration(address resource) external view override {
        ISpokeComptroller comptrollerContract = ISpokeComptroller(IVTokenIsolated(resource).comptroller());
        if (!comptrollerContract.isMarketListed(resource)) revert MarketNotListed(resource);
        if (
            comptrollerContract.isSupplyAllowlistEnabled(resource) &&
            !comptrollerContract.isAllowedSupplier(resource, msg.sender)
        ) {
            revert SupplyNotAllowed(resource, msg.sender);
        }
    }

    // ============================== Private — pure ===========================

    /**
     * @notice Underlying value of exactly one vToken, rounded up.
     * @param exchangeRate Market's stored exchange rate, scaled by `1e18`.
     * @return unit `ceil(exchangeRate / 1e18)`.
     */
    function _oneVTokenUnit(uint256 exchangeRate) private pure returns (uint256 unit) {
        return (exchangeRate + EXP_SCALE - 1) / EXP_SCALE;
    }

    /**
     * @notice Fewest vTokens worth at least `amount` of underlying.
     * @dev `ceil(amount x 1e18 / exchangeRate)`. A token-denominated redeem pays
     *      `truncate(exchangeRate x tokens)`, and this ceiling is the smallest count whose payout
     *      reaches `amount` — so {withdraw} never under-delivers, and never burns more than
     *      {maxWithdraw} certified the position and the market's cash can cover.
     *
     *      Non-increasing in the exchange rate. The market accrues before redeeming and that rate
     *      only ever rises, so a count sized here stays inside the balance at execution and its
     *      payout stays at or above `amount`.
     * @param exchangeRate Market's stored exchange rate, scaled by `1e18`.
     * @param amount Underlying units the caller intends to redeem.
     * @return tokens vToken units to burn.
     */
    function _burnFor(uint256 exchangeRate, uint256 amount) private pure returns (uint256 tokens) {
        if (exchangeRate == 0) return 0;
        return (amount * EXP_SCALE + exchangeRate - 1) / exchangeRate;
    }
}

contracts/test/HubSpoke/interfaces/exter.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { SpokeComptrollerViewInterface } from "../../../../Spoke/SpokeComptrollerInterface.sol";

/**
 * @title ISpokeComptroller
 * @author Venus
 * @notice The name `AdapterSpokeV1` imports for its view of a spoke pool. In `venus-liquidity-hub` this is a
 *         hand-written copy of the five getters the adapter calls, because that repo does not depend on this one. Here
 *         the name is bound to this repo's own `SpokeComptrollerViewInterface`, so the adapter compiles against the
 *         declarations the pool actually ships rather than against a second copy of them that nothing keeps in step.
 * @dev `isMarketListed` is the one getter declared here. `SpokeComptrollerViewInterface` does not carry it, because the
 *      pool implements it with a `VToken` parameter, as the shared `Comptroller` does. Both encode as
 *      `isMarketListed(address)`, so the adapter calls the selector the pool answers.
 *
 *      The hub's copy still exists on its side of the boundary and still has to match. `tests/hardhat/Spoke/
 *      interfaces.ts` checks these declarations against the compiled `SpokeComptroller`, and `tests/hardhat/Fork/
 *      HubSpoke/interfaces.ts` calls them on the deployed pool.
 */
interface ISpokeComptroller is SpokeComptrollerViewInterface {
    /**
     * @notice Whether the Comptroller lists `vToken` as one of its markets
     * @param vToken The market to query
     * @return listed True if `vToken` is a listed market of this Comptroller
     */
    function isMarketListed(address vToken) external view returns (bool listed);
}

contracts/test/UpgradedSpokeComptroller..content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { SpokeComptroller } from "../Spoke/SpokeComptroller.sol";

/**
 * @title UpgradedSpokeComptroller
 * @notice Test-only successor implementation for the spoke beacon.
 * @dev Appends one variable and one function, which is the shape a real upgrade takes. Lets the tests prove that the
 * existing storage survives a beacon upgrade and that the appended slot starts empty. Never deployed to a network.
 */
contract UpgradedSpokeComptroller is SpokeComptroller {
    /// @notice Value only the upgraded implementation knows about
    uint256 public addedAfterUpgrade;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address poolRegistry_) SpokeComptroller(poolRegistry_) {}

    /// @notice Writes the appended variable, so a test can tell a live upgrade from a no-op
    function setAddedAfterUpgrade(uint256 value) external {
        addedAfterUpgrade = value;
    }
}

contracts/VToken.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { SafeERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";
import { IProtocolShareReserve } from "@venusprotocol/protocol-reserve/contracts/Interfaces/IProtocolShareReserve.sol";

import { VTokenInterface } from "./VTokenInterfaces.sol";
import { ComptrollerInterface, ComptrollerViewInterface } from "./ComptrollerInterface.sol";
import { TokenErrorReporter } from "./ErrorReporter.sol";
import { InterestRateModel } from "./InterestRateModel.sol";
import { ExponentialNoError } from "./ExponentialNoError.sol";
import { TimeManagerV8 } from "@venusprotocol/solidity-utilities/contracts/TimeManagerV8.sol";
import { ensureNonzeroAddress } from "./lib/validators.sol";

/**
 * @title VToken
 * @author Venus
 * @notice Each asset that is supported by a pool is integrated through an instance of the `VToken` contract. As outlined in the protocol overview,
 * each isolated pool creates its own `vToken` corresponding to an asset. Within a given pool, each included `vToken` is referred to as a market of
 * the pool. The main actions a user regularly interacts with in a market are:

- mint/redeem of vTokens;
- transfer of vTokens;
- borrow/repay a loan on an underlying asset;
- liquidate a borrow or liquidate/heal an account.

 * A user supplies the underlying asset to a pool by minting `vTokens`, where the corresponding `vToken` amount is determined by the `exchangeRate`.
 * The `exchangeRate` will change over time, dependent on a number of factors, some of which accrue interest. Additionally, once users have minted
 * `vToken` in a pool, they can borrow any asset in the isolated pool by using their `vToken` as collateral. In order to borrow an asset or use a `vToken`
 * as collateral, the user must be entered into each corresponding market (else, the `vToken` will not be considered collateral for a borrow). Note that
 * a user may borrow up to a portion of their collateral determined by the market’s collateral factor. However, if their borrowed amount exceeds an amount
 * calculated using the market’s corresponding liquidation threshold, the borrow is eligible for liquidation. When a user repays a borrow, they must also
 * pay off interest accrued on the borrow.
 * 
 * The Venus protocol includes unique mechanisms for healing an account and liquidating an account. These actions are performed in the `Comptroller`
 * and consider all borrows and collateral for which a given account is entered within a market. These functions may only be called on an account with a
 * total collateral amount that is no larger than a universal `minLiquidatableCollateral` value, which is used for all markets within a `Comptroller`.
 * Both functions settle all of an account’s borrows, but `healAccount()` may add `badDebt` to a vToken. For more detail, see the description of
 * `healAccount()` and `liquidateAccount()` in the `Comptroller` summary section below.
 */
contract VToken is
    Ownable2StepUpgradeable,
    AccessControlledV8,
    VTokenInterface,
    ExponentialNoError,
    TokenErrorReporter,
    TimeManagerV8
{
    using SafeERC20Upgradeable for IERC20Upgradeable;

    uint256 internal constant DEFAULT_PROTOCOL_SEIZE_SHARE_MANTISSA = 5e16; // 5%

    // Maximum fraction of interest that can be set aside for reserves
    uint256 internal constant MAX_RESERVE_FACTOR_MANTISSA = 1e18;

    // Maximum borrow rate that can ever be applied per slot(block or second)
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    uint256 internal immutable MAX_BORROW_RATE_MANTISSA;

    /**
     * Reentrancy Guard **
     */

    /**
     * @dev Prevents a contract from calling itself, directly or indirectly.
     */
    modifier nonReentrant() {
        require(_notEntered, "re-entered");
        _notEntered = false;
        _;
        _notEntered = true; // get a gas-refund post-Istanbul
    }

    /**
     * @param timeBased_ A boolean indicating whether the contract is based on time or block.
     * @param blocksPerYear_ The number of blocks per year
     * @param maxBorrowRateMantissa_ The maximum value of borrowing rate mantissa
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(
        bool timeBased_,
        uint256 blocksPerYear_,
        uint256 maxBorrowRateMantissa_
    ) TimeManagerV8(timeBased_, blocksPerYear_) {
        // Note that the contract is upgradeable. Use initialize() or reinitializers
        // to set the state variables.
        require(maxBorrowRateMantissa_ <= 1e18, "Max borrow rate must be <= 1e18");

        MAX_BORROW_RATE_MANTISSA = maxBorrowRateMantissa_;
        _disableInitializers();
    }

    /**
     * @notice Construct a new money market
     * @param underlying_ The address of the underlying asset
     * @param comptroller_ The address of the Comptroller
     * @param interestRateModel_ The address of the interest rate model
     * @param initialExchangeRateMantissa_ The initial exchange rate, scaled by 1e18
     * @param name_ ERC-20 name of this token
     * @param symbol_ ERC-20 symbol of this token
     * @param decimals_ ERC-20 decimal precision of this token
     * @param admin_ Address of the administrator of this token
     * @param accessControlManager_ AccessControlManager contract address
     * @param riskManagement Addresses of risk & income related contracts
     * @param reserveFactorMantissa_ Percentage of borrow interest that goes to reserves (from 0 to 1e18)
     * @custom:error ZeroAddressNotAllowed is thrown when admin address is zero
     * @custom:error ZeroAddressNotAllowed is thrown when shortfall contract address is zero
     * @custom:error ZeroAddressNotAllowed is thrown when protocol share reserve address is zero
     */
    function initialize(
        address underlying_,
        ComptrollerInterface comptroller_,
        InterestRateModel interestRateModel_,
        uint256 initialExchangeRateMantissa_,
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        address admin_,
        address accessControlManager_,
        RiskManagementInit memory riskManagement,
        uint256 reserveFactorMantissa_
    ) external initializer {
        ensureNonzeroAddress(admin_);

        // Initialize the market
        _initialize(
            underlying_,
            comptroller_,
            interestRateModel_,
            initialExchangeRateMantissa_,
            name_,
            symbol_,
            decimals_,
            admin_,
            accessControlManager_,
            riskManagement,
            reserveFactorMantissa_
        );
    }

    /**
     * @notice Transfer `amount` tokens from `msg.sender` to `dst`
     * @param dst The address of the destination account
     * @param amount The number of tokens to transfer
     * @return success True if the transfer succeeded, reverts otherwise
     * @custom:event Emits Transfer event on success
     * @custom:error TransferNotAllowed is thrown if trying to transfer to self
     * @custom:access Not restricted
     */
    function transfer(address dst, uint256 amount) external override nonReentrant returns (bool) {
        _transferTokens(msg.sender, msg.sender, dst, amount);
        return true;
    }

    /**
     * @notice Transfer `amount` tokens from `src` to `dst`
     * @param src The address of the source account
     * @param dst The address of the destination account
     * @param amount The number of tokens to transfer
     * @return success True if the transfer succeeded, reverts otherwise
     * @custom:event Emits Transfer event on success
     * @custom:error TransferNotAllowed is thrown if trying to transfer to self
     * @custom:access Not restricted
     */
    function transferFrom(address src, address dst, uint256 amount) external override nonReentrant returns (bool) {
        _transferTokens(msg.sender, src, dst, amount);
        return true;
    }

    /**
     * @notice Approve `spender` to transfer up to `amount` from `src`
     * @dev This will overwrite the approval amount for `spender`
     *  and is subject to issues noted [here](https://eips.ethereum.org/EIPS/eip-20#approve)
     * @param spender The address of the account which may transfer tokens
     * @param amount The number of tokens that are approved (uint256.max means infinite)
     * @return success Whether or not the approval succeeded
     * @custom:event Emits Approval event
     * @custom:access Not restricted
     * @custom:error ZeroAddressNotAllowed is thrown when spender address is zero
     */
    function approve(address spender, uint256 amount) external override returns (bool) {
        ensureNonzeroAddress(spender);

        address src = msg.sender;
        transferAllowances[src][spender] = amount;
        emit Approval(src, spender, amount);
        return true;
    }

    /**
     * @notice Increase approval for `spender`
     * @param spender The address of the account which may transfer tokens
     * @param addedValue The number of additional tokens spender can transfer
     * @return success Whether or not the approval succeeded
     * @custom:event Emits Approval event
     * @custom:access Not restricted
     * @custom:error ZeroAddressNotAllowed is thrown when spender address is zero
     */
    function increaseAllowance(address spender, uint256 addedValue) external override returns (bool) {
        ensureNonzeroAddress(spender);

        address src = msg.sender;
        uint256 newAllowance = transferAllowances[src][spender];
        newAllowance += addedValue;
        transferAllowances[src][spender] = newAllowance;

        emit Approval(src, spender, newAllowance);
        return true;
    }

    /**
     * @notice Decreases approval for `spender`
     * @param spender The address of the account which may transfer tokens
     * @param subtractedValue The number of tokens to remove from total approval
     * @return success Whether or not the approval succeeded
     * @custom:event Emits Approval event
     * @custom:access Not restricted
     * @custom:error ZeroAddressNotAllowed is thrown when spender address is zero
     */
    function decreaseAllowance(address spender, uint256 subtractedValue) external override returns (bool) {
        ensureNonzeroAddress(spender);

        address src = msg.sender;
        uint256 currentAllowance = transferAllowances[src][spender];
        require(currentAllowance >= subtractedValue, "decreased allowance below zero");
        unchecked {
            currentAllowance -= subtractedValue;
        }

        transferAllowances[src][spender] = currentAllowance;

        emit Approval(src, spender, currentAllowance);
        return true;
    }

    /**
     * @notice Get the underlying balance of the `owner`
     * @dev This also accrues interest in a transaction
     * @param owner The address of the account to query
     * @return amount The amount of underlying owned by `owner`
     */
    function balanceOfUnderlying(address owner) external override returns (uint256) {
        Exp memory exchangeRate = Exp({ mantissa: exchangeRateCurrent() });
        return mul_ScalarTruncate(exchangeRate, accountTokens[owner]);
    }

    /**
     * @notice Returns the current total borrows plus accrued interest
     * @return totalBorrows The total borrows with interest
     */
    function totalBorrowsCurrent() external override nonReentrant returns (uint256) {
        accrueInterest();
        return totalBorrows;
    }

    /**
     * @notice Accrue interest to updated borrowIndex and then calculate account's borrow balance using the updated borrowIndex
     * @param account The address whose balance should be calculated after updating borrowIndex
     * @return borrowBalance The calculated balance
     */
    function borrowBalanceCurrent(address account) external override nonReentrant returns (uint256) {
        accrueInterest();
        return _borrowBalanceStored(account);
    }

    /**
     * @notice Sender supplies assets into the market and receives vTokens in exchange
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param mintAmount The amount of the underlying asset to supply
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits Mint and Transfer events; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function mint(uint256 mintAmount) external override nonReentrant returns (uint256) {
        accrueInterest();

        _mintFresh(msg.sender, msg.sender, mintAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender calls on-behalf of minter. minter supplies assets into the market and receives vTokens in exchange
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param minter User whom the supply will be attributed to
     * @param mintAmount The amount of the underlying asset to supply
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits Mint and Transfer events; may emit AccrueInterest
     * @custom:access Not restricted
     * @custom:error ZeroAddressNotAllowed is thrown when minter address is zero
     */
    function mintBehalf(address minter, uint256 mintAmount) external override nonReentrant returns (uint256) {
        ensureNonzeroAddress(minter);

        accrueInterest();

        _mintFresh(msg.sender, minter, mintAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender redeems vTokens in exchange for the underlying asset
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param redeemTokens The number of vTokens to redeem into underlying
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits Redeem and Transfer events; may emit AccrueInterest
     * @custom:error RedeemTransferOutNotPossible is thrown when the protocol has insufficient cash
     * @custom:access Not restricted
     */
    function redeem(uint256 redeemTokens) external override nonReentrant returns (uint256) {
        accrueInterest();

        _redeemFresh(msg.sender, msg.sender, redeemTokens, 0);
        return NO_ERROR;
    }

    /**
     * @notice Sender redeems assets on behalf of some other address. This function is only available
     *   for senders, explicitly marked as delegates of the supplier using `comptroller.updateDelegate`
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param redeemer The user on behalf of whom to redeem
     * @param redeemTokens The number of vTokens to redeem into underlying
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:error InsufficientRedeemApproval is thrown when sender is not approved by the redeemer for the given amount
     * @custom:error RedeemTransferOutNotPossible is thrown when the protocol has insufficient cash
     * @custom:event Emits Redeem and Transfer events; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function redeemBehalf(address redeemer, uint256 redeemTokens) external override nonReentrant returns (uint256) {
        _ensureSenderIsDelegateOf(redeemer);

        accrueInterest();

        _redeemFresh(redeemer, msg.sender, redeemTokens, 0);
        return NO_ERROR;
    }

    /**
     * @notice Sender redeems vTokens in exchange for a specified amount of underlying asset
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param redeemAmount The amount of underlying to receive from redeeming vTokens
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     */
    function redeemUnderlying(uint256 redeemAmount) external override nonReentrant returns (uint256) {
        accrueInterest();

        _redeemFresh(msg.sender, msg.sender, 0, redeemAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender redeems underlying assets on behalf of some other address. This function is only available
     *   for senders, explicitly marked as delegates of the supplier using `comptroller.updateDelegate`
     * @dev Accrues interest whether or not the operation succeeds, unless reverted
     * @param redeemer, on behalf of whom to redeem
     * @param redeemAmount The amount of underlying to receive from redeeming vTokens
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:error InsufficientRedeemApproval is thrown when sender is not approved by the redeemer for the given amount
     * @custom:event Emits Redeem and Transfer events; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function redeemUnderlyingBehalf(
        address redeemer,
        uint256 redeemAmount
    ) external override nonReentrant returns (uint256) {
        _ensureSenderIsDelegateOf(redeemer);

        accrueInterest();

        _redeemFresh(redeemer, msg.sender, 0, redeemAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender borrows assets from the protocol to their own address
     * @param borrowAmount The amount of the underlying asset to borrow
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits Borrow event; may emit AccrueInterest
     * @custom:error BorrowCashNotAvailable is thrown when the protocol has insufficient cash
     * @custom:access Not restricted
     */
    function borrow(uint256 borrowAmount) external override nonReentrant returns (uint256) {
        accrueInterest();

        _borrowFresh(msg.sender, msg.sender, borrowAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender borrows assets on behalf of some other address. This function is only available
     *   for senders, explicitly marked as delegates of the borrower using `comptroller.updateDelegate`
     * @param borrower The borrower, on behalf of whom to borrow
     * @param borrowAmount The amount of the underlying asset to borrow
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:error DelegateNotApproved is thrown if caller is not approved delegate
     * @custom:error BorrowCashNotAvailable is thrown when the protocol has insufficient cash
     * @custom:event Emits Borrow event; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function borrowBehalf(address borrower, uint256 borrowAmount) external override returns (uint256) {
        _ensureSenderIsDelegateOf(borrower);
        accrueInterest();

        _borrowFresh(borrower, msg.sender, borrowAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender repays their own borrow
     * @param repayAmount The amount to repay, or type(uint256).max for the full outstanding amount
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits RepayBorrow event; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function repayBorrow(uint256 repayAmount) external override nonReentrant returns (uint256) {
        accrueInterest();

        _repayBorrowFresh(msg.sender, msg.sender, repayAmount);
        return NO_ERROR;
    }

    /**
     * @notice Sender repays a borrow belonging to borrower
     * @param borrower the account with the debt being payed off
     * @param repayAmount The amount to repay, or type(uint256).max for the full outstanding amount
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits RepayBorrow event; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function repayBorrowBehalf(address borrower, uint256 repayAmount) external override nonReentrant returns (uint256) {
        accrueInterest();

        _repayBorrowFresh(msg.sender, borrower, repayAmount);
        return NO_ERROR;
    }

    /**
     * @notice The sender liquidates the borrowers collateral.
     *  The collateral seized is transferred to the liquidator.
     * @param borrower The borrower of this vToken to be liquidated
     * @param repayAmount The amount of the underlying borrowed asset to repay
     * @param vTokenCollateral The market in which to seize collateral from the borrower
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @custom:event Emits LiquidateBorrow event; may emit AccrueInterest
     * @custom:error LiquidateAccrueCollateralInterestFailed is thrown when it is not possible to accrue interest on the collateral vToken
     * @custom:error LiquidateCollateralFreshnessCheck is thrown when interest has not been accrued on the collateral vToken
     * @custom:error LiquidateLiquidatorIsBorrower is thrown when trying to liquidate self
     * @custom:error LiquidateCloseAmountIsZero is thrown when repayment amount is zero
     * @custom:error LiquidateCloseAmountIsUintMax is thrown when repayment amount is UINT_MAX
     * @custom:access Not restricted
     */
    function liquidateBorrow(
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral
    ) external override returns (uint256) {
        _liquidateBorrow(msg.sender, borrower, repayAmount, vTokenCollateral, false);
        return NO_ERROR;
    }

    /**
     * @notice sets protocol share accumulated from liquidations
     * @dev must be equal or less than liquidation incentive - 1
     * @param newProtocolSeizeShareMantissa_ new protocol share mantissa
     * @custom:event Emits NewProtocolSeizeShare event on success
     * @custom:error Unauthorized error is thrown when the call is not authorized by AccessControlManager
     * @custom:error ProtocolSeizeShareTooBig is thrown when the new seize share is too high
     * @custom:access Controlled by AccessControlManager
     */
    function setProtocolSeizeShare(uint256 newProtocolSeizeShareMantissa_) external {
        _checkAccessAllowed("setProtocolSeizeShare(uint256)");
        uint256 liquidationIncentive = ComptrollerViewInterface(address(comptroller)).liquidationIncentiveMantissa();
        if (newProtocolSeizeShareMantissa_ + MANTISSA_ONE > liquidationIncentive) {
            revert ProtocolSeizeShareTooBig();
        }

        uint256 oldProtocolSeizeShareMantissa = protocolSeizeShareMantissa;
        protocolSeizeShareMantissa = newProtocolSeizeShareMantissa_;
        emit NewProtocolSeizeShare(oldProtocolSeizeShareMantissa, newProtocolSeizeShareMantissa_);
    }

    /**
     * @notice accrues interest and sets a new reserve factor for the protocol using _setReserveFactorFresh
     * @dev Admin function to accrue interest and set a new reserve factor
     * @param newReserveFactorMantissa New reserve factor (from 0 to 1e18)
     * @custom:event Emits NewReserveFactor event; may emit AccrueInterest
     * @custom:error Unauthorized error is thrown when the call is not authorized by AccessControlManager
     * @custom:error SetReserveFactorBoundsCheck is thrown when the new reserve factor is too high
     * @custom:access Controlled by AccessControlManager
     */
    function setReserveFactor(uint256 newReserveFactorMantissa) external override nonReentrant {
        _checkAccessAllowed("setReserveFactor(uint256)");

        accrueInterest();
        _setReserveFactorFresh(newReserveFactorMantissa);
    }

    /**
     * @notice Accrues interest and reduces reserves by transferring to the protocol reserve contract
     * @dev Gracefully return if reserves already reduced in accrueInterest
     * @param reduceAmount Amount of reduction to reserves
     * @custom:event Emits ReservesReduced event; may emit AccrueInterest
     * @custom:error ReduceReservesCashNotAvailable is thrown when the vToken does not have sufficient cash
     * @custom:error ReduceReservesCashValidation is thrown when trying to withdraw more cash than the reserves have
     * @custom:access Not restricted
     */
    function reduceReserves(uint256 reduceAmount) external override nonReentrant {
        accrueInterest();
        if (reduceReservesBlockNumber == getBlockNumberOrTimestamp()) return;
        _reduceReservesFresh(reduceAmount);
    }

    /**
     * @notice The sender adds to reserves.
     * @param addAmount The amount of underlying token to add as reserves
     * @custom:event Emits ReservesAdded event; may emit AccrueInterest
     * @custom:access Not restricted
     */
    function addReserves(uint256 addAmount) external override nonReentrant {
        accrueInterest();
        _addReservesFresh(addAmount);
    }

    /**
     * @notice accrues interest and updates the interest rate model using _setInterestRateModelFresh
     * @dev Admin function to accrue interest and update the interest rate model
     * @param newInterestRateModel the new interest rate model to use
     * @custom:event Emits NewMarketInterestRateModel event; may emit AccrueInterest
     * @custom:error Unauthorized error is thrown when the call is not authorized by AccessControlManager
     * @custom:access Controlled by AccessControlManager
     */
    function setInterestRateModel(InterestRateModel newInterestRateModel) external override {
        _checkAccessAllowed("setInterestRateModel(address)");

        accrueInterest();
        _setInterestRateModelFresh(newInterestRateModel);
    }

    /**
     * @notice Repays a certain amount of debt, treats the rest of the borrow as bad debt, essentially
     *   "forgiving" the borrower. Healing is a situation that should rarely happen. However, some pools
     *   may list risky assets or be configured improperly – we want to still handle such cases gracefully.
     *   We assume that Comptroller does the seizing, so this function is only available to Comptroller.
     * @dev This function does not call any Comptroller hooks (like "healAllowed"), because we assume
     *   the Comptroller does all the necessary checks before calling this function.
     * @param payer account who repays the debt
     * @param borrower account to heal
     * @param repayAmount amount to repay
     * @custom:event Emits RepayBorrow, BadDebtIncreased events; may emit AccrueInterest
     * @custom:error HealBorrowUnauthorized is thrown when the request does not come from Comptroller
     * @custom:access Only Comptroller
     */
    function healBorrow(address payer, address borrower, uint256 repayAmount) external override nonReentrant {
        if (repayAmount != 0) {
            comptroller.preRepayHook(address(this), borrower);
        }

        if (msg.sender != address(comptroller)) {
            revert HealBorrowUnauthorized();
        }

        uint256 accountBorrowsPrev = _borrowBalanceStored(borrower);
        uint256 totalBorrowsNew = totalBorrows;

        uint256 actualRepayAmount;
        if (repayAmount != 0) {
            // _doTransferIn reverts if anything goes wrong, since we can't be sure if side effects occurred.
            // We violate checks-effects-interactions here to account for tokens that take transfer fees
            actualRepayAmount = _doTransferIn(payer, repayAmount);
            totalBorrowsNew = totalBorrowsNew - actualRepayAmount;
            emit RepayBorrow(
                payer,
                borrower,
                actualRepayAmount,
                accountBorrowsPrev - actualRepayAmount,
                totalBorrowsNew
            );
        }

        // The transaction will fail if trying to repay too much
        uint256 badDebtDelta = accountBorrowsPrev - actualRepayAmount;
        if (badDebtDelta != 0) {
            uint256 badDebtOld = badDebt;
            uint256 badDebtNew = badDebtOld + badDebtDelta;
            totalBorrowsNew = totalBorrowsNew - badDebtDelta;
            badDebt = badDebtNew;

            // We treat healing as "repayment", where vToken is the payer
            emit RepayBorrow(address(this), borrower, badDebtDelta, 0, totalBorrowsNew);
            emit BadDebtIncreased(borrower, badDebtDelta, badDebtOld, badDebtNew);
        }

        accountBorrows[borrower].principal = 0;
        accountBorrows[borrower].interestIndex = borrowIndex;
        totalBorrows = totalBorrowsNew;

        emit HealBorrow(payer, borrower, repayAmount);
    }

    /**
     * @notice The extended version of liquidations, callable only by Comptroller. May skip
     *  the close factor check. The collateral seized is transferred to the liquidator.
     * @param liquidator The address repaying the borrow and seizing collateral
     * @param borrower The borrower of this vToken to be liquidated
     * @param repayAmount The amount of the underlying borrowed asset to repay
     * @param vTokenCollateral The market in which to seize collateral from the borrower
     * @param skipLiquidityCheck If set to true, allows to liquidate up to 100% of the borrow
     *   regardless of the account liquidity
     * @custom:event Emits LiquidateBorrow event; may emit AccrueInterest
     * @custom:error ForceLiquidateBorrowUnauthorized is thrown when the request does not come from Comptroller
     * @custom:error LiquidateAccrueCollateralInterestFailed is thrown when it is not possible to accrue interest on the collateral vToken
     * @custom:error LiquidateCollateralFreshnessCheck is thrown when interest has not been accrued on the collateral vToken
     * @custom:error LiquidateLiquidatorIsBorrower is thrown when trying to liquidate self
     * @custom:error LiquidateCloseAmountIsZero is thrown when repayment amount is zero
     * @custom:error LiquidateCloseAmountIsUintMax is thrown when repayment amount is UINT_MAX
     * @custom:access Only Comptroller
     */
    function forceLiquidateBorrow(
        address liquidator,
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral,
        bool skipLiquidityCheck
    ) external override {
        if (msg.sender != address(comptroller)) {
            revert ForceLiquidateBorrowUnauthorized();
        }
        _liquidateBorrow(liquidator, borrower, repayAmount, vTokenCollateral, skipLiquidityCheck);
    }

    /**
     * @notice Transfers collateral tokens (this market) to the liquidator.
     * @dev Will fail unless called by another vToken during the process of liquidation.
     *  It's absolutely critical to use msg.sender as the borrowed vToken and not a parameter.
     * @param liquidator The account receiving seized collateral
     * @param borrower The account having collateral seized
     * @param seizeTokens The number of vTokens to seize
     * @custom:event Emits Transfer, ReservesAdded events
     * @custom:error LiquidateSeizeLiquidatorIsBorrower is thrown when trying to liquidate self
     * @custom:access Not restricted
     */
    function seize(address liquidator, address borrower, uint256 seizeTokens) external override nonReentrant {
        _seize(msg.sender, liquidator, borrower, seizeTokens);
    }

    /**
     * @notice Updates bad debt
     * @dev Called only when bad debt is recovered from auction. Updates internal cash balance.
     * @param recoveredAmount_ The amount of bad debt recovered
     * @custom:event Emits BadDebtRecovered event
     * @custom:access Only Shortfall contract
     */
    function badDebtRecovered(uint256 recoveredAmount_) external {
        require(msg.sender == shortfall, "only shortfall contract can update bad debt");
        require(recoveredAmount_ <= badDebt, "more than bad debt recovered from auction");

        uint256 badDebtOld = badDebt;
        uint256 badDebtNew = badDebtOld - recoveredAmount_;
        badDebt = badDebtNew;
        internalCash += recoveredAmount_;

        emit BadDebtRecovered(badDebtOld, badDebtNew);
    }

    /**
     * @notice Sets protocol share reserve contract address
     * @param protocolShareReserve_ The address of the protocol share reserve contract
     * @custom:error ZeroAddressNotAllowed is thrown when protocol share reserve address is zero
     * @custom:access Only Governance
     */
    function setProtocolShareReserve(address payable protocolShareReserve_) external onlyOwner {
        _setProtocolShareReserve(protocolShareReserve_);
    }

    /**
     * @notice Sets shortfall contract address
     * @param shortfall_ The address of the shortfall contract
     * @custom:error ZeroAddressNotAllowed is thrown when shortfall contract address is zero
     * @custom:access Only Governance
     */
    function setShortfallContract(address shortfall_) external onlyOwner {
        _setShortfallContract(shortfall_);
    }

    /**
     * @notice A public function to sweep accidental ERC-20 transfers to this contract. Tokens are sent to admin (timelock)
     * @param token The address of the ERC-20 token to sweep
     * @custom:access Only Governance
     */
    function sweepToken(IERC20Upgradeable token) external override {
        require(msg.sender == owner(), "VToken::sweepToken: only admin can sweep tokens");
        require(address(token) != underlying, "VToken::sweepToken: can not sweep underlying token");
        uint256 balance = token.balanceOf(address(this));
        token.safeTransfer(owner(), balance);

        emit SweepToken(address(token));
    }

    /**
     * @notice Sync internalCash with the actual underlying token balance
     * @dev Used for one-time migration after upgrade to initialize internalCash
     * @custom:event Emits CashSynced
     * @custom:access Controlled by AccessControlManager
     */
    function syncCash() external override nonReentrant {
        _checkAccessAllowed("syncCash()");
        uint256 oldInternalCash = internalCash;
        uint256 actualCash = IERC20Upgradeable(underlying).balanceOf(address(this));
        internalCash = actualCash;
        emit CashSynced(oldInternalCash, actualCash);
    }

    /**
     * @notice A public function to set new threshold of slot(block or second) difference after which funds will be sent to the protocol share reserve
     * @param _newReduceReservesBlockOrTimestampDelta slot(block or second) difference value
     * @custom:access Only Governance
     */
    function setReduceReservesBlockDelta(uint256 _newReduceReservesBlockOrTimestampDelta) external {
        _checkAccessAllowed("setReduceReservesBlockDelta(uint256)");
        require(_newReduceReservesBlockOrTimestampDelta > 0, "Invalid Input");
        emit NewReduceReservesBlockDelta(reduceReservesBlockDelta, _newReduceReservesBlockOrTimestampDelta);
        reduceReservesBlockDelta = _newReduceReservesBlockOrTimestampDelta;
    }

    /**
     * @notice Get the current allowance from `owner` for `spender`
     * @param owner The address of the account which owns the tokens to be spent
     * @param spender The address of the account which may transfer tokens
     * @return amount The number of tokens allowed to be spent (type(uint256).max means infinite)
     */
    function allowance(address owner, address spender) external view override returns (uint256) {
        return transferAllowances[owner][spender];
    }

    /**
     * @notice Get the token balance of the `owner`
     * @param owner The address of the account to query
     * @return amount The number of tokens owned by `owner`
     */
    function balanceOf(address owner) external view override returns (uint256) {
        return accountTokens[owner];
    }

    /**
     * @notice Get a snapshot of the account's balances, and the cached exchange rate
     * @dev This is used by comptroller to more efficiently perform liquidity checks.
     * @param account Address of the account to snapshot
     * @return error Always NO_ERROR for compatibility with Venus core tooling
     * @return vTokenBalance User's balance of vTokens
     * @return borrowBalance Amount owed in terms of underlying
     * @return exchangeRate Stored exchange rate
     */
    function getAccountSnapshot(
        address account
    )
        external
        view
        override
        returns (uint256 error, uint256 vTokenBalance, uint256 borrowBalance, uint256 exchangeRate)
    {
        return (NO_ERROR, accountTokens[account], _borrowBalanceStored(account), _exchangeRateStored());
    }

    /**
     * @notice Get the internally tracked cash balance of this vToken in the underlying asset
     * @return cash The quantity of underlying asset tracked internally by this contract
     */
    function getCash() external view override returns (uint256) {
        return _getCashPrior();
    }

    /**
     * @notice Returns the current per slot(block or second) borrow interest rate for this vToken
     * @return rate The borrow interest rate per slot(block or second), scaled by 1e18
     */
    function borrowRatePerBlock() external view override returns (uint256) {
        return interestRateModel.getBorrowRate(_getCashPrior(), totalBorrows, totalReserves, badDebt);
    }

    /**
     * @notice Returns the current per-slot(block or second) supply interest rate for this v
     * @return rate The supply interest rate per slot(block or second), scaled by 1e18
     */
    function supplyRatePerBlock() external view override returns (uint256) {
        return
            interestRateModel.getSupplyRate(
                _getCashPrior(),
                totalBorrows,
                totalReserves,
                reserveFactorMantissa,
                badDebt
            );
    }

    /**
     * @notice Return the borrow balance of account based on stored data
     * @param account The address whose balance should be calculated
     * @return borrowBalance The calculated balance
     */
    function borrowBalanceStored(address account) external view override returns (uint256) {
        return _borrowBalanceStored(account);
    }

    /**
     * @notice Calculates the exchange rate from the underlying to the VToken
     * @dev This function does not accrue interest before calculating the exchange rate
     * @return exchangeRate Calculated exchange rate scaled by 1e18
     */
    function exchangeRateStored() external view override returns (uint256) {
        return _exchangeRateStored();
    }

    /**
     * @notice Accrue interest then return the up-to-date exchange rate
     * @return exchangeRate Calculated exchange rate scaled by 1e18
     */
    function exchangeRateCurrent() public override nonReentrant returns (uint256) {
        accrueInterest();
        return _exchangeRateStored();
    }

    /**
     * @notice Applies accrued interest to total borrows and reserves
     * @dev This calculates interest accrued from the last checkpointed slot(block or second)
     *  up to the current slot(block or second) and writes new checkpoint to storage and
     *  reduce spread reserves to protocol share reserve
     *  if currentSlot - reduceReservesBlockNumber >= slotDelta
     * @return Always NO_ERROR
     * @custom:event Emits AccrueInterest event on success
     * @custom:access Not restricted
     */
    function accrueInterest() public virtual override returns (uint256) {
        /* Remember the initial block number or timestamp */
        uint256 currentSlotNumber = getBlockNumberOrTimestamp();
        uint256 accrualSlotNumberPrior = accrualBlockNumber;

        /* Short-circuit accumulating 0 interest */
        if (accrualSlotNumberPrior == currentSlotNumber) {
            return NO_ERROR;
        }

        /* Read the previous values out of storage */
        uint256 cashPrior = _getCashPrior();
        uint256 borrowsPrior = totalBorrows;
        uint256 reservesPrior = totalReserves;
        uint256 borrowIndexPrior = borrowIndex;

        /* Calculate the current borrow interest rate */
        uint256 borrowRateMantissa = interestRateModel.getBorrowRate(cashPrior, borrowsPrior, reservesPrior, badDebt);
        require(borrowRateMantissa <= MAX_BORROW_RATE_MANTISSA, "borrow rate is absurdly high");

        /* Calculate the number of slots elapsed since the last accrual */
        uint256 slotDelta = currentSlotNumber - accrualSlotNumberPrior;

        /*
         * Calculate the interest accumulated into borrows and reserves and the new index:
         *  simpleInterestFactor = borrowRate * slotDelta
         *  interestAccumulated = simpleInterestFactor * totalBorrows
         *  totalBorrowsNew = interestAccumulated + totalBorrows
         *  totalReservesNew = interestAccumulated * reserveFactor + totalReserves
         *  borrowIndexNew = simpleInterestFactor * borrowIndex + borrowIndex
         */

        Exp memory simpleInterestFactor = mul_(Exp({ mantissa: borrowRateMantissa }), slotDelta);
        uint256 interestAccumulated = mul_ScalarTruncate(simpleInterestFactor, borrowsPrior);
        uint256 totalBorrowsNew = interestAccumulated + borrowsPrior;
        uint256 totalReservesNew = mul_ScalarTruncateAddUInt(
            Exp({ mantissa: reserveFactorMantissa }),
            interestAccumulated,
            reservesPrior
        );
        uint256 borrowIndexNew = mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /* We write the previously calculated values into storage */
        accrualBlockNumber = currentSlotNumber;
        borrowIndex = borrowIndexNew;
        totalBorrows = totalBorrowsNew;
        totalReserves = totalReservesNew;

        if (currentSlotNumber - reduceReservesBlockNumber >= reduceReservesBlockDelta) {
            reduceReservesBlockNumber = currentSlotNumber;
            if (cashPrior < totalReservesNew) {
                _reduceReservesFresh(cashPrior);
            } else {
                _reduceReservesFresh(totalReservesNew);
            }
        }

        /* We emit an AccrueInterest event */
        emit AccrueInterest(cashPrior, interestAccumulated, borrowIndexNew, totalBorrowsNew);

        return NO_ERROR;
    }

    /**
     * @notice User supplies assets into the market and receives vTokens in exchange
     * @dev Assumes interest has already been accrued up to the current block or timestamp
     * @param payer The address of the account which is sending the assets for supply
     * @param minter The address of the account which is supplying the assets
     * @param mintAmount The amount of the underlying asset to supply
     */
    function _mintFresh(address payer, address minter, uint256 mintAmount) internal {
        /* Fail if mint not allowed */
        comptroller.preMintHook(address(this), minter, mintAmount);

        /* Verify market's slot(block or second) number equals current slot(block or second) number */
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert MintFreshnessCheck();
        }

        Exp memory exchangeRate = Exp({ mantissa: _exchangeRateStored() });

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /*
         *  We call `_doTransferIn` for the minter and the mintAmount.
         *  `_doTransferIn` reverts if anything goes wrong, since we can't be sure if
         *  side-effects occurred. The function returns the amount actually transferred,
         *  in case of a fee. On success, the vToken holds an additional `actualMintAmount`
         *  of cash.
         */
        uint256 actualMintAmount = _doTransferIn(payer, mintAmount);

        /*
         * We get the current exchange rate and calculate the number of vTokens to be minted:
         *  mintTokens = actualMintAmount / exchangeRate
         */

        uint256 mintTokens = div_(actualMintAmount, exchangeRate);

        /*
         * We calculate the new total supply of vTokens and minter token balance, checking for overflow:
         *  totalSupplyNew = totalSupply + mintTokens
         *  accountTokensNew = accountTokens[minter] + mintTokens
         * And write them into storage
         */
        totalSupply = totalSupply + mintTokens;
        uint256 balanceAfter = accountTokens[minter] + mintTokens;
        accountTokens[minter] = balanceAfter;

        /* We emit a Mint event, and a Transfer event */
        emit Mint(minter, actualMintAmount, mintTokens, balanceAfter);
        emit Transfer(address(0), minter, mintTokens);

        /* We call the defense and prime accrue interest hook */
        comptroller.mintVerify(address(this), minter, actualMintAmount, mintTokens);
    }

    /**
     * @notice Redeemer redeems vTokens in exchange for the underlying assets, transferred to the receiver. Redeemer and receiver can be the same
     *   address, or different addresses if the receiver was previously approved by the redeemer as a valid delegate (see Comptroller.updateDelegate)
     * @dev Assumes interest has already been accrued up to the current slot(block or second)
     * @param redeemer The address of the account which is redeeming the tokens
     * @param receiver The receiver of the underlying tokens
     * @param redeemTokensIn The number of vTokens to redeem into underlying (only one of redeemTokensIn or redeemAmountIn may be non-zero)
     * @param redeemAmountIn The number of underlying tokens to receive from redeeming vTokens (only one of redeemTokensIn or redeemAmountIn may be non-zero)
     */
    function _redeemFresh(address redeemer, address receiver, uint256 redeemTokensIn, uint256 redeemAmountIn) internal {
        require(redeemTokensIn == 0 || redeemAmountIn == 0, "one of redeemTokensIn or redeemAmountIn must be zero");

        /* Verify market's slot(block or second) number equals current slot(block or second) number */
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert RedeemFreshnessCheck();
        }

        /* exchangeRate = invoke Exchange Rate Stored() */
        Exp memory exchangeRate = Exp({ mantissa: _exchangeRateStored() });

        uint256 redeemTokens;
        uint256 redeemAmount;

        /* If redeemTokensIn > 0: */
        if (redeemTokensIn > 0) {
            /*
             * We calculate the exchange rate and the amount of underlying to be redeemed:
             *  redeemTokens = redeemTokensIn
             */
            redeemTokens = redeemTokensIn;
        } else {
            /*
             * We get the current exchange rate and calculate the amount to be redeemed:
             *  redeemTokens = redeemAmountIn / exchangeRate
             */
            redeemTokens = div_(redeemAmountIn, exchangeRate);

            uint256 _redeemAmount = mul_(redeemTokens, exchangeRate);
            if (_redeemAmount != 0 && _redeemAmount != redeemAmountIn) redeemTokens++; // round up
        }

        // redeemAmount = exchangeRate * redeemTokens
        redeemAmount = mul_ScalarTruncate(exchangeRate, redeemTokens);

        // Revert if amount is zero
        if (redeemAmount == 0) {
            revert("redeemAmount is zero");
        }

        /* Fail if redeem not allowed */
        comptroller.preRedeemHook(address(this), redeemer, redeemTokens);

        /* Fail gracefully if protocol has insufficient cash */
        if (_getCashPrior() - totalReserves < redeemAmount) {
            revert RedeemTransferOutNotPossible();
        }

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /*
         * We write the previously calculated values into storage.
         *  Note: Avoid token reentrancy attacks by writing reduced supply before external transfer.
         */
        totalSupply = totalSupply - redeemTokens;
        uint256 balanceAfter = accountTokens[redeemer] - redeemTokens;
        accountTokens[redeemer] = balanceAfter;

        /*
         * We invoke _doTransferOut for the receiver and the redeemAmount.
         *  On success, the vToken has redeemAmount less of cash.
         *  _doTransferOut reverts if anything goes wrong, since we can't be sure if side effects occurred.
         */
        _doTransferOut(receiver, redeemAmount);

        /* We emit a Transfer event, and a Redeem event */
        emit Transfer(redeemer, address(this), redeemTokens);
        emit Redeem(redeemer, redeemAmount, redeemTokens, balanceAfter);

        /* We call the defense and prime accrue interest hook */
        comptroller.redeemVerify(address(this), redeemer, redeemAmount, redeemTokens);
    }

    /**
     * @notice Users or their delegates borrow assets from the protocol
     * @param borrower User who borrows the assets
     * @param receiver The receiver of the tokens, if called by a delegate
     * @param borrowAmount The amount of the underlying asset to borrow
     */
    function _borrowFresh(address borrower, address receiver, uint256 borrowAmount) internal {
        /* Fail if borrow not allowed */
        comptroller.preBorrowHook(address(this), borrower, borrowAmount);

        /* Verify market's slot(block or second) number equals current slot(block or second) number */
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert BorrowFreshnessCheck();
        }

        /* Fail gracefully if protocol has insufficient underlying cash */
        if (_getCashPrior() - totalReserves < borrowAmount) {
            revert BorrowCashNotAvailable();
        }

        /*
         * We calculate the new borrower and total borrow balances, failing on overflow:
         *  accountBorrowNew = accountBorrow + borrowAmount
         *  totalBorrowsNew = totalBorrows + borrowAmount
         */
        uint256 accountBorrowsPrev = _borrowBalanceStored(borrower);
        uint256 accountBorrowsNew = accountBorrowsPrev + borrowAmount;
        uint256 totalBorrowsNew = totalBorrows + borrowAmount;

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /*
         * We write the previously calculated values into storage.
         *  Note: Avoid token reentrancy attacks by writing increased borrow before external transfer.
        `*/
        accountBorrows[borrower].principal = accountBorrowsNew;
        accountBorrows[borrower].interestIndex = borrowIndex;
        totalBorrows = totalBorrowsNew;

        /*
         * We invoke _doTransferOut for the receiver and the borrowAmount.
         *  On success, the vToken borrowAmount less of cash.
         *  _doTransferOut reverts if anything goes wrong, since we can't be sure if side effects occurred.
         */
        _doTransferOut(receiver, borrowAmount);

        /* We emit a Borrow event */
        emit Borrow(borrower, borrowAmount, accountBorrowsNew, totalBorrowsNew);

        /* We call the defense and prime accrue interest hook */
        comptroller.borrowVerify(address(this), borrower, borrowAmount);
    }

    /**
     * @notice Borrows are repaid by another user (possibly the borrower).
     * @param payer the account paying off the borrow
     * @param borrower the account with the debt being payed off
     * @param repayAmount the amount of underlying tokens being returned, or type(uint256).max for the full outstanding amount
     * @return (uint) the actual repayment amount.
     */
    function _repayBorrowFresh(address payer, address borrower, uint256 repayAmount) internal returns (uint256) {
        /* Fail if repayBorrow not allowed */
        comptroller.preRepayHook(address(this), borrower);

        /* Verify market's slot(block or second) number equals current slot(block or second) number */
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert RepayBorrowFreshnessCheck();
        }

        /* We fetch the amount the borrower owes, with accumulated interest */
        uint256 accountBorrowsPrev = _borrowBalanceStored(borrower);

        uint256 repayAmountFinal = repayAmount >= accountBorrowsPrev ? accountBorrowsPrev : repayAmount;

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /*
         * We call _doTransferIn for the payer and the repayAmount
         *  On success, the vToken holds an additional repayAmount of cash.
         *  _doTransferIn reverts if anything goes wrong, since we can't be sure if side effects occurred.
         *   it returns the amount actually transferred, in case of a fee.
         */
        uint256 actualRepayAmount = _doTransferIn(payer, repayAmountFinal);

        /*
         * We calculate the new borrower and total borrow balances, failing on underflow:
         *  accountBorrowsNew = accountBorrows - actualRepayAmount
         *  totalBorrowsNew = totalBorrows - actualRepayAmount
         */
        uint256 accountBorrowsNew = accountBorrowsPrev - actualRepayAmount;
        uint256 totalBorrowsNew = totalBorrows - actualRepayAmount;

        /* We write the previously calculated values into storage */
        accountBorrows[borrower].principal = accountBorrowsNew;
        accountBorrows[borrower].interestIndex = borrowIndex;
        totalBorrows = totalBorrowsNew;

        /* We emit a RepayBorrow event */
        emit RepayBorrow(payer, borrower, actualRepayAmount, accountBorrowsNew, totalBorrowsNew);

        /* We call the defense and prime accrue interest hook */
        comptroller.repayBorrowVerify(address(this), payer, borrower, actualRepayAmount, borrowIndex);

        return actualRepayAmount;
    }

    /**
     * @notice The sender liquidates the borrowers collateral.
     *  The collateral seized is transferred to the liquidator.
     * @param liquidator The address repaying the borrow and seizing collateral
     * @param borrower The borrower of this vToken to be liquidated
     * @param repayAmount The amount of the underlying borrowed asset to repay
     * @param vTokenCollateral The market in which to seize collateral from the borrower
     * @param skipLiquidityCheck If set to true, allows to liquidate up to 100% of the borrow
     *   regardless of the account liquidity
     */
    function _liquidateBorrow(
        address liquidator,
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral,
        bool skipLiquidityCheck
    ) internal nonReentrant {
        accrueInterest();

        uint256 error = vTokenCollateral.accrueInterest();
        if (error != NO_ERROR) {
            // accrueInterest emits logs on errors, but we still want to log the fact that an attempted liquidation failed
            revert LiquidateAccrueCollateralInterestFailed(error);
        }

        _liquidateBorrowFresh(liquidator, borrower, repayAmount, vTokenCollateral, skipLiquidityCheck);
    }

    /**
     * @notice The liquidator liquidates the borrowers collateral.
     *  The collateral seized is transferred to the liquidator.
     * @param liquidator The address repaying the borrow and seizing collateral
     * @param borrower The borrower of this vToken to be liquidated
     * @param repayAmount The amount of the underlying borrowed asset to repay
     * @param vTokenCollateral The market in which to seize collateral from the borrower
     * @param skipLiquidityCheck If set to true, allows to liquidate up to 100% of the borrow
     *   regardless of the account liquidity
     */
    function _liquidateBorrowFresh(
        address liquidator,
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral,
        bool skipLiquidityCheck
    ) internal {
        /* Fail if liquidate not allowed */
        comptroller.preLiquidateHook(
            address(this),
            address(vTokenCollateral),
            borrower,
            repayAmount,
            skipLiquidityCheck
        );

        /* Verify market's slot(block or second) number equals current slot(block or second) number */
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert LiquidateFreshnessCheck();
        }

        /* Verify vTokenCollateral market's slot(block or second) number equals current slot(block or second) number */
        if (vTokenCollateral.accrualBlockNumber() != getBlockNumberOrTimestamp()) {
            revert LiquidateCollateralFreshnessCheck();
        }

        /* Fail if borrower = liquidator */
        if (borrower == liquidator) {
            revert LiquidateLiquidatorIsBorrower();
        }

        /* Fail if repayAmount = 0 */
        if (repayAmount == 0) {
            revert LiquidateCloseAmountIsZero();
        }

        /* Fail if repayAmount = type(uint256).max */
        if (repayAmount == type(uint256).max) {
            revert LiquidateCloseAmountIsUintMax();
        }

        /* Fail if repayBorrow fails */
        uint256 actualRepayAmount = _repayBorrowFresh(liquidator, borrower, repayAmount);

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /* We calculate the number of collateral tokens that will be seized */
        (uint256 amountSeizeError, uint256 seizeTokens) = comptroller.liquidateCalculateSeizeTokens(
            address(this),
            address(vTokenCollateral),
            actualRepayAmount
        );
        require(amountSeizeError == NO_ERROR, "LIQUIDATE_COMPTROLLER_CALCULATE_AMOUNT_SEIZE_FAILED");

        /* Revert if borrower collateral token balance < seizeTokens */
        require(vTokenCollateral.balanceOf(borrower) >= seizeTokens, "LIQUIDATE_SEIZE_TOO_MUCH");

        // If this is also the collateral, call _seize internally to avoid re-entrancy, otherwise make an external call
        if (address(vTokenCollateral) == address(this)) {
            _seize(address(this), liquidator, borrower, seizeTokens);
        } else {
            vTokenCollateral.seize(liquidator, borrower, seizeTokens);
        }

        /* We emit a LiquidateBorrow event */
        emit LiquidateBorrow(liquidator, borrower, actualRepayAmount, address(vTokenCollateral), seizeTokens);

        /* We call the defense and prime accrue interest hook */
        comptroller.liquidateBorrowVerify(
            address(this),
            address(vTokenCollateral),
            liquidator,
            borrower,
            actualRepayAmount,
            seizeTokens
        );
    }

    /**
     * @notice Transfers collateral tokens (this market) to the liquidator.
     * @dev Called only during an in-kind liquidation, or by liquidateBorrow during the liquidation of another VToken.
     *  It's absolutely critical to use msg.sender as the seizer vToken and not a parameter.
     * @param seizerContract The contract seizing the collateral (either borrowed vToken or Comptroller)
     * @param liquidator The account receiving seized collateral
     * @param borrower The account having collateral seized
     * @param seizeTokens The number of vTokens to seize
     */
    function _seize(address seizerContract, address liquidator, address borrower, uint256 seizeTokens) internal {
        /* Fail if seize not allowed */
        comptroller.preSeizeHook(address(this), seizerContract, liquidator, borrower);

        /* Fail if borrower = liquidator */
        if (borrower == liquidator) {
            revert LiquidateSeizeLiquidatorIsBorrower();
        }

        /*
         * We calculate the new borrower and liquidator token balances, failing on underflow/overflow:
         *  borrowerTokensNew = accountTokens[borrower] - seizeTokens
         *  liquidatorTokensNew = accountTokens[liquidator] + seizeTokens
         */
        uint256 liquidationIncentiveMantissa = ComptrollerViewInterface(address(comptroller))
            .liquidationIncentiveMantissa();
        uint256 numerator = mul_(seizeTokens, Exp({ mantissa: protocolSeizeShareMantissa }));
        uint256 protocolSeizeTokens = div_(numerator, Exp({ mantissa: liquidationIncentiveMantissa }));
        uint256 liquidatorSeizeTokens = seizeTokens - protocolSeizeTokens;
        Exp memory exchangeRate = Exp({ mantissa: _exchangeRateStored() });
        uint256 protocolSeizeAmount = mul_ScalarTruncate(exchangeRate, protocolSeizeTokens);

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        /* We write the calculated values into storage */
        totalSupply = totalSupply - protocolSeizeTokens;
        accountTokens[borrower] = accountTokens[borrower] - seizeTokens;
        accountTokens[liquidator] = accountTokens[liquidator] + liquidatorSeizeTokens;

        // _doTransferOut reverts if anything goes wrong, since we can't be sure if side effects occurred.
        // Transferring an underlying asset to the protocolShareReserve contract to channel the funds for different use.
        _doTransferOut(protocolShareReserve, protocolSeizeAmount);

        // Update the pool asset's state in the protocol share reserve for the above transfer.
        IProtocolShareReserve(protocolShareReserve).updateAssetsState(
            address(comptroller),
            underlying,
            IProtocolShareReserve.IncomeType.LIQUIDATION
        );

        /* Emit a Transfer event */
        emit Transfer(borrower, liquidator, liquidatorSeizeTokens);
        emit ProtocolSeize(borrower, protocolShareReserve, protocolSeizeAmount);

        /* We call the defense and prime accrue interest hook */
        comptroller.seizeVerify(address(this), seizerContract, liquidator, borrower, seizeTokens);
    }

    function _setComptroller(ComptrollerInterface newComptroller) internal {
        ComptrollerInterface oldComptroller = comptroller;
        // Ensure invoke comptroller.isComptroller() returns true
        require(newComptroller.isComptroller(), "marker method returned false");

        // Set market's comptroller to newComptroller
        comptroller = newComptroller;

        // Emit NewComptroller(oldComptroller, newComptroller)
        emit NewComptroller(oldComptroller, newComptroller);
    }

    /**
     * @notice Sets a new reserve factor for the protocol (*requires fresh interest accrual)
     * @dev Admin function to set a new reserve factor
     * @param newReserveFactorMantissa New reserve factor (from 0 to 1e18)
     */
    function _setReserveFactorFresh(uint256 newReserveFactorMantissa) internal {
        // Verify market's slot(block or second) number equals current slot(block or second) number
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert SetReserveFactorFreshCheck();
        }

        // Check newReserveFactor ≤ maxReserveFactor
        if (newReserveFactorMantissa > MAX_RESERVE_FACTOR_MANTISSA) {
            revert SetReserveFactorBoundsCheck();
        }

        uint256 oldReserveFactorMantissa = reserveFactorMantissa;
        reserveFactorMantissa = newReserveFactorMantissa;

        emit NewReserveFactor(oldReserveFactorMantissa, newReserveFactorMantissa);
    }

    /**
     * @notice Add reserves by transferring from caller
     * @dev Requires fresh interest accrual
     * @param addAmount Amount of addition to reserves
     * @return actualAddAmount The actual amount added, excluding the potential token fees
     */
    function _addReservesFresh(uint256 addAmount) internal returns (uint256) {
        // totalReserves + actualAddAmount
        uint256 totalReservesNew;
        uint256 actualAddAmount;

        // We fail gracefully unless market's slot(block or second) number equals current slot(block or second) number
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert AddReservesFactorFreshCheck(actualAddAmount);
        }

        actualAddAmount = _doTransferIn(msg.sender, addAmount);
        totalReservesNew = totalReserves + actualAddAmount;
        totalReserves = totalReservesNew;
        emit ReservesAdded(msg.sender, actualAddAmount, totalReservesNew);

        return actualAddAmount;
    }

    /**
     * @notice Reduces reserves by transferring to the protocol reserve contract
     * @dev Requires fresh interest accrual
     * @param reduceAmount Amount of reduction to reserves
     */
    function _reduceReservesFresh(uint256 reduceAmount) internal {
        if (reduceAmount == 0) {
            return;
        }
        // totalReserves - reduceAmount
        uint256 totalReservesNew;

        // We fail gracefully unless market's slot(block or second) number equals current slot(block or second) number
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert ReduceReservesFreshCheck();
        }

        // Fail gracefully if protocol has insufficient underlying cash
        if (_getCashPrior() < reduceAmount) {
            revert ReduceReservesCashNotAvailable();
        }

        // Check reduceAmount ≤ reserves[n] (totalReserves)
        if (reduceAmount > totalReserves) {
            revert ReduceReservesCashValidation();
        }

        /////////////////////////
        // EFFECTS & INTERACTIONS
        // (No safe failures beyond this point)

        totalReservesNew = totalReserves - reduceAmount;

        // Store reserves[n+1] = reserves[n] - reduceAmount
        totalReserves = totalReservesNew;

        // _doTransferOut reverts if anything goes wrong, since we can't be sure if side effects occurred.
        // Transferring an underlying asset to the protocolShareReserve contract to channel the funds for different use.
        _doTransferOut(protocolShareReserve, reduceAmount);

        // Update the pool asset's state in the protocol share reserve for the above transfer.
        IProtocolShareReserve(protocolShareReserve).updateAssetsState(
            address(comptroller),
            underlying,
            IProtocolShareReserve.IncomeType.SPREAD
        );

        emit SpreadReservesReduced(protocolShareReserve, reduceAmount, totalReservesNew);
    }

    /**
     * @notice updates the interest rate model (*requires fresh interest accrual)
     * @dev Admin function to update the interest rate model
     * @param newInterestRateModel the new interest rate model to use
     */
    function _setInterestRateModelFresh(InterestRateModel newInterestRateModel) internal {
        // Used to store old model for use in the event that is emitted on success
        InterestRateModel oldInterestRateModel;

        // We fail gracefully unless market's slot(block or second) number equals current slot(block or second) number
        if (accrualBlockNumber != getBlockNumberOrTimestamp()) {
            revert SetInterestRateModelFreshCheck();
        }

        // Track the market's current interest rate model
        oldInterestRateModel = interestRateModel;

        // Ensure invoke newInterestRateModel.isInterestRateModel() returns true
        require(newInterestRateModel.isInterestRateModel(), "marker method returned false");

        // Set the interest rate model to newInterestRateModel
        interestRateModel = newInterestRateModel;

        // Emit NewMarketInterestRateModel(oldInterestRateModel, newInterestRateModel)
        emit NewMarketInterestRateModel(oldInterestRateModel, newInterestRateModel);
    }

    /**
     * Safe Token **
     */

    /**
     * @dev Similar to ERC-20 transfer, but handles tokens that have transfer fees.
     *      This function returns the actual amount received,
     *      which may be less than `amount` if there is a fee attached to the transfer.
     * @param from Sender of the underlying tokens
     * @param amount Amount of underlying to transfer
     * @return Actual amount received
     */
    function _doTransferIn(address from, uint256 amount) internal virtual returns (uint256) {
        IERC20Upgradeable token = IERC20Upgradeable(underlying);
        uint256 balanceBefore = token.balanceOf(address(this));
        token.safeTransferFrom(from, address(this), amount);
        uint256 balanceAfter = token.balanceOf(address(this));
        uint256 actualAmount = balanceAfter - balanceBefore;
        internalCash += actualAmount;
        // Return the amount that was *actually* transferred
        return actualAmount;
    }

    /**
     * @dev Just a regular ERC-20 transfer, reverts on failure
     * @param to Receiver of the underlying tokens
     * @param amount Amount of underlying to transfer
     */
    function _doTransferOut(address to, uint256 amount) internal virtual {
        IERC20Upgradeable token = IERC20Upgradeable(underlying);
        internalCash -= amount;
        token.safeTransfer(to, amount);
    }

    /**
     * @notice Transfer `tokens` tokens from `src` to `dst` by `spender`
     * @dev Called by both `transfer` and `transferFrom` internally
     * @param spender The address of the account performing the transfer
     * @param src The address of the source account
     * @param dst The address of the destination account
     * @param tokens The number of tokens to transfer
     */
    function _transferTokens(address spender, address src, address dst, uint256 tokens) internal {
        /* Fail if transfer not allowed */
        comptroller.preTransferHook(address(this), src, dst, tokens);

        /* Do not allow self-transfers */
        if (src == dst) {
            revert TransferNotAllowed();
        }

        /* Get the allowance, infinite for the account owner */
        uint256 startingAllowance;
        if (spender == src) {
            startingAllowance = type(uint256).max;
        } else {
            startingAllowance = transferAllowances[src][spender];
        }

        /* Do the calculations, checking for {under,over}flow */
        uint256 allowanceNew = startingAllowance - tokens;
        uint256 srcTokensNew = accountTokens[src] - tokens;
        uint256 dstTokensNew = accountTokens[dst] + tokens;

        /////////////////////////
        // EFFECTS & INTERACTIONS

        accountTokens[src] = srcTokensNew;
        accountTokens[dst] = dstTokensNew;

        /* Eat some of the allowance (if necessary) */
        if (startingAllowance != type(uint256).max) {
            transferAllowances[src][spender] = allowanceNew;
        }

        /* We emit a Transfer event */
        emit Transfer(src, dst, tokens);

        comptroller.transferVerify(address(this), src, dst, tokens);
    }

    /**
     * @notice Initialize the money market
     * @param underlying_ The address of the underlying asset
     * @param comptroller_ The address of the Comptroller
     * @param interestRateModel_ The address of the interest rate model
     * @param initialExchangeRateMantissa_ The initial exchange rate, scaled by 1e18
     * @param name_ ERC-20 name of this token
     * @param symbol_ ERC-20 symbol of this token
     * @param decimals_ ERC-20 decimal precision of this token
     * @param admin_ Address of the administrator of this token
     * @param accessControlManager_ AccessControlManager contract address
     * @param riskManagement Addresses of risk & income related contracts
     * @param reserveFactorMantissa_ Percentage of borrow interest that goes to reserves (from 0 to 1e18)
     */
    function _initialize(
        address underlying_,
        ComptrollerInterface comptroller_,
        InterestRateModel interestRateModel_,
        uint256 initialExchangeRateMantissa_,
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        address admin_,
        address accessControlManager_,
        RiskManagementInit memory riskManagement,
        uint256 reserveFactorMantissa_
    ) internal onlyInitializing {
        __Ownable2Step_init();
        __AccessControlled_init_unchained(accessControlManager_);
        require(accrualBlockNumber == 0 && borrowIndex == 0, "market may only be initialized once");

        // Set initial exchange rate
        initialExchangeRateMantissa = initialExchangeRateMantissa_;
        require(initialExchangeRateMantissa > 0, "initial exchange rate must be greater than zero.");

        _setComptroller(comptroller_);

        // Initialize slot(block or second) number and borrow index (slot(block or second) number mocks depend on comptroller being set)
        accrualBlockNumber = getBlockNumberOrTimestamp();
        borrowIndex = MANTISSA_ONE;

        // Set the interest rate model (depends on slot(block or second) number / borrow index)
        _setInterestRateModelFresh(interestRateModel_);

        _setReserveFactorFresh(reserveFactorMantissa_);

        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        _setShortfallContract(riskManagement.shortfall);
        _setProtocolShareReserve(riskManagement.protocolShareReserve);
        protocolSeizeShareMantissa = DEFAULT_PROTOCOL_SEIZE_SHARE_MANTISSA;

        // Set underlying and sanity check it
        underlying = underlying_;
        IERC20Upgradeable(underlying).totalSupply();

        // The counter starts true to prevent changing it from zero to non-zero (i.e. smaller cost/refund)
        _notEntered = true;
        _transferOwnership(admin_);
    }

    function _setShortfallContract(address shortfall_) internal {
        ensureNonzeroAddress(shortfall_);
        address oldShortfall = shortfall;
        shortfall = shortfall_;
        emit NewShortfallContract(oldShortfall, shortfall_);
    }

    function _setProtocolShareReserve(address payable protocolShareReserve_) internal {
        ensureNonzeroAddress(protocolShareReserve_);
        address oldProtocolShareReserve = address(protocolShareReserve);
        protocolShareReserve = protocolShareReserve_;
        emit NewProtocolShareReserve(oldProtocolShareReserve, address(protocolShareReserve_));
    }

    function _ensureSenderIsDelegateOf(address user) internal view {
        if (!ComptrollerViewInterface(address(comptroller)).approvedDelegates(user, msg.sender)) {
            revert DelegateNotApproved();
        }
    }

    /**
     * @notice Gets the internally tracked cash balance of this market
     * @dev Returns the internalCash state variable, which is updated on transfers in/out
     * @return The quantity of underlying tokens tracked internally by this contract
     */
    function _getCashPrior() internal view virtual returns (uint256) {
        return internalCash;
    }

    /**
     * @notice Return the borrow balance of account based on stored data
     * @param account The address whose balance should be calculated
     * @return borrowBalance the calculated balance
     */
    function _borrowBalanceStored(address account) internal view returns (uint256) {
        /* Get borrowBalance and borrowIndex */
        BorrowSnapshot memory borrowSnapshot = accountBorrows[account];

        /* If borrowBalance = 0 then borrowIndex is likely also 0.
         * Rather than failing the calculation with a division by 0, we immediately return 0 in this case.
         */
        if (borrowSnapshot.principal == 0) {
            return 0;
        }

        /* Calculate new borrow balance using the interest index:
         *  recentBorrowBalance = borrower.borrowBalance * market.borrowIndex / borrower.borrowIndex
         */
        uint256 principalTimesIndex = borrowSnapshot.principal * borrowIndex;

        return principalTimesIndex / borrowSnapshot.interestIndex;
    }

    /**
     * @notice Calculates the exchange rate from the underlying to the VToken
     * @dev This function does not accrue interest before calculating the exchange rate
     * @return exchangeRate Calculated exchange rate scaled by 1e18
     */
    function _exchangeRateStored() internal view virtual returns (uint256) {
        uint256 _totalSupply = totalSupply;
        if (_totalSupply == 0) {
            /*
             * If there are no tokens minted:
             *  exchangeRate = initialExchangeRate
             */
            return initialExchangeRateMantissa;
        }
        /*
         * Otherwise:
         *  exchangeRate = (totalCash + totalBorrows + badDebt - totalReserves) / totalSupply
         */
        uint256 totalCash = _getCashPrior();
        uint256 cashPlusBorrowsMinusReserves = totalCash + totalBorrows + badDebt - totalReserves;
        uint256 exchangeRate = (cashPlusBorrowsMinusReserves * EXP_SCALE) / _totalSupply;

        return exchangeRate;
    }
}

contracts/VTokenInterfaces.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.25;

import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";

import { ComptrollerInterface } from "./ComptrollerInterface.sol";
import { InterestRateModel } from "./InterestRateModel.sol";

/**
 * @title VTokenStorage
 * @author Venus
 * @notice Storage layout used by the `VToken` contract
 */
// solhint-disable-next-line max-states-count
contract VTokenStorage {
    /**
     * @notice Container for borrow balance information
     * @member principal Total balance (with accrued interest), after applying the most recent balance-changing action
     * @member interestIndex Global borrowIndex as of the most recent balance-changing action
     */
    struct BorrowSnapshot {
        uint256 principal;
        uint256 interestIndex;
    }

    /**
     * @dev Guard variable for re-entrancy checks
     */
    bool internal _notEntered;

    /**
     * @notice Underlying asset for this VToken
     */
    address public underlying;

    /**
     * @notice EIP-20 token name for this token
     */
    string public name;

    /**
     * @notice EIP-20 token symbol for this token
     */
    string public symbol;

    /**
     * @notice EIP-20 token decimals for this token
     */
    uint8 public decimals;

    /**
     * @notice Protocol share Reserve contract address
     */
    address payable public protocolShareReserve;

    /**
     * @notice Contract which oversees inter-vToken operations
     */
    ComptrollerInterface public comptroller;

    /**
     * @notice Model which tells what the current interest rate should be
     */
    InterestRateModel public interestRateModel;

    // Initial exchange rate used when minting the first VTokens (used when totalSupply = 0)
    uint256 internal initialExchangeRateMantissa;

    /**
     * @notice Fraction of interest currently set aside for reserves
     */
    uint256 public reserveFactorMantissa;

    /**
     * @notice Slot(block or second) number that interest was last accrued at
     */
    uint256 public accrualBlockNumber;

    /**
     * @notice Accumulator of the total earned interest rate since the opening of the market
     */
    uint256 public borrowIndex;

    /**
     * @notice Total amount of outstanding borrows of the underlying in this market
     */
    uint256 public totalBorrows;

    /**
     * @notice Total amount of reserves of the underlying held in this market
     */
    uint256 public totalReserves;

    /**
     * @notice Total number of tokens in circulation
     */
    uint256 public totalSupply;

    /**
     * @notice Total bad debt of the market
     */
    uint256 public badDebt;

    // Official record of token balances for each account
    mapping(address => uint256) internal accountTokens;

    // Approved token transfer amounts on behalf of others
    mapping(address => mapping(address => uint256)) internal transferAllowances;

    // Mapping of account addresses to outstanding borrow balances
    mapping(address => BorrowSnapshot) internal accountBorrows;

    /**
     * @notice Share of seized collateral that is added to reserves
     */
    uint256 public protocolSeizeShareMantissa;

    /**
     * @notice Storage of Shortfall contract address
     */
    address public shortfall;

    /**
     * @notice delta slot (block or second) after which reserves will be reduced
     */
    uint256 public reduceReservesBlockDelta;

    /**
     * @notice last slot (block or second) number at which reserves were reduced
     */
    uint256 public reduceReservesBlockNumber;

    /**
     * @notice Tracked internal cash balance, immune to direct token transfers (donation attacks)
     * @dev Updated via _doTransferIn(), _doTransferOut(), syncCash(), and badDebtRecovered(). Must be initialized via syncCash() after upgrade.
     */
    uint256 public internalCash;

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[47] private __gap;
}

/**
 * @title VTokenInterface
 * @author Venus
 * @notice Interface implemented by the `VToken` contract
 */
abstract contract VTokenInterface is VTokenStorage {
    struct RiskManagementInit {
        address shortfall;
        address payable protocolShareReserve;
    }

    /*** Market Events ***/

    /**
     * @notice Event emitted when interest is accrued
     */
    event AccrueInterest(uint256 cashPrior, uint256 interestAccumulated, uint256 borrowIndex, uint256 totalBorrows);

    /**
     * @notice Event emitted when tokens are minted
     */
    event Mint(address indexed minter, uint256 mintAmount, uint256 mintTokens, uint256 accountBalance);

    /**
     * @notice Event emitted when tokens are redeemed
     */
    event Redeem(address indexed redeemer, uint256 redeemAmount, uint256 redeemTokens, uint256 accountBalance);

    /**
     * @notice Event emitted when underlying is borrowed
     */
    event Borrow(address indexed borrower, uint256 borrowAmount, uint256 accountBorrows, uint256 totalBorrows);

    /**
     * @notice Event emitted when a borrow is repaid
     */
    event RepayBorrow(
        address indexed payer,
        address indexed borrower,
        uint256 repayAmount,
        uint256 accountBorrows,
        uint256 totalBorrows
    );

    /**
     * @notice Event emitted when bad debt is accumulated on a market
     * @param borrower borrower to "forgive"
     * @param badDebtDelta amount of new bad debt recorded
     * @param badDebtOld previous bad debt value
     * @param badDebtNew new bad debt value
     */
    event BadDebtIncreased(address indexed borrower, uint256 badDebtDelta, uint256 badDebtOld, uint256 badDebtNew);

    /**
     * @notice Event emitted when bad debt is recovered via an auction
     * @param badDebtOld previous bad debt value
     * @param badDebtNew new bad debt value
     */
    event BadDebtRecovered(uint256 badDebtOld, uint256 badDebtNew);

    /**
     * @notice Event emitted when a borrow is liquidated
     */
    event LiquidateBorrow(
        address indexed liquidator,
        address indexed borrower,
        uint256 repayAmount,
        address indexed vTokenCollateral,
        uint256 seizeTokens
    );

    /*** Admin Events ***/

    /**
     * @notice Event emitted when comptroller is changed
     */
    event NewComptroller(ComptrollerInterface indexed oldComptroller, ComptrollerInterface indexed newComptroller);

    /**
     * @notice Event emitted when shortfall contract address is changed
     */
    event NewShortfallContract(address indexed oldShortfall, address indexed newShortfall);

    /**
     * @notice Event emitted when protocol share reserve contract address is changed
     */
    event NewProtocolShareReserve(address indexed oldProtocolShareReserve, address indexed newProtocolShareReserve);

    /**
     * @notice Event emitted when interestRateModel is changed
     */
    event NewMarketInterestRateModel(
        InterestRateModel indexed oldInterestRateModel,
        InterestRateModel indexed newInterestRateModel
    );

    /**
     * @notice Event emitted when protocol seize share is changed
     */
    event NewProtocolSeizeShare(uint256 oldProtocolSeizeShareMantissa, uint256 newProtocolSeizeShareMantissa);

    /**
     * @notice Event emitted when the reserve factor is changed
     */
    event NewReserveFactor(uint256 oldReserveFactorMantissa, uint256 newReserveFactorMantissa);

    /**
     * @notice Event emitted when the reserves are added
     */
    event ReservesAdded(address indexed benefactor, uint256 addAmount, uint256 newTotalReserves);

    /**
     * @notice Event emitted when the spread reserves are reduced
     */
    event SpreadReservesReduced(address indexed protocolShareReserve, uint256 reduceAmount, uint256 newTotalReserves);

    /**
     * @notice EIP20 Transfer event
     */
    event Transfer(address indexed from, address indexed to, uint256 amount);

    /**
     * @notice EIP20 Approval event
     */
    event Approval(address indexed owner, address indexed spender, uint256 amount);

    /**
     * @notice Event emitted when healing the borrow
     */
    event HealBorrow(address indexed payer, address indexed borrower, uint256 repayAmount);

    /**
     * @notice Event emitted when tokens are swept
     */
    event SweepToken(address indexed token);

    /**
     * @notice Event emitted when reduce reserves slot (block or second) delta is changed
     */
    event NewReduceReservesBlockDelta(
        uint256 oldReduceReservesBlockOrTimestampDelta,
        uint256 newReduceReservesBlockOrTimestampDelta
    );

    /**
     * @notice Event emitted when liquidation reserves are reduced
     */
    event ProtocolSeize(address indexed from, address indexed to, uint256 amount);

    /**
     * @notice Event emitted when internalCash is synced with actual token balance
     */
    event CashSynced(uint256 oldInternalCash, uint256 newInternalCash);

    /*** User Interface ***/

    function mint(uint256 mintAmount) external virtual returns (uint256);

    function mintBehalf(address minter, uint256 mintAllowed) external virtual returns (uint256);

    function redeem(uint256 redeemTokens) external virtual returns (uint256);

    function redeemBehalf(address redeemer, uint256 redeemTokens) external virtual returns (uint256);

    function redeemUnderlying(uint256 redeemAmount) external virtual returns (uint256);

    function redeemUnderlyingBehalf(address redeemer, uint256 redeemAmount) external virtual returns (uint256);

    function borrow(uint256 borrowAmount) external virtual returns (uint256);

    function borrowBehalf(address borrwwer, uint256 borrowAmount) external virtual returns (uint256);

    function repayBorrow(uint256 repayAmount) external virtual returns (uint256);

    function repayBorrowBehalf(address borrower, uint256 repayAmount) external virtual returns (uint256);

    function liquidateBorrow(
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral
    ) external virtual returns (uint256);

    function healBorrow(address payer, address borrower, uint256 repayAmount) external virtual;

    function forceLiquidateBorrow(
        address liquidator,
        address borrower,
        uint256 repayAmount,
        VTokenInterface vTokenCollateral,
        bool skipCloseFactorCheck
    ) external virtual;

    function seize(address liquidator, address borrower, uint256 seizeTokens) external virtual;

    function transfer(address dst, uint256 amount) external virtual returns (bool);

    function transferFrom(address src, address dst, uint256 amount) external virtual returns (bool);

    function accrueInterest() external virtual returns (uint256);

    function sweepToken(IERC20Upgradeable token) external virtual;

    /*** Admin Functions ***/

    function setReserveFactor(uint256 newReserveFactorMantissa) external virtual;

    function reduceReserves(uint256 reduceAmount) external virtual;

    function exchangeRateCurrent() external virtual returns (uint256);

    function borrowBalanceCurrent(address account) external virtual returns (uint256);

    function setInterestRateModel(InterestRateModel newInterestRateModel) external virtual;

    function addReserves(uint256 addAmount) external virtual;

    function syncCash() external virtual;

    function totalBorrowsCurrent() external virtual returns (uint256);

    function balanceOfUnderlying(address owner) external virtual returns (uint256);

    function approve(address spender, uint256 amount) external virtual returns (bool);

    function increaseAllowance(address spender, uint256 addedValue) external virtual returns (bool);

    function decreaseAllowance(address spender, uint256 subtractedValue) external virtual returns (bool);

    function allowance(address owner, address spender) external view virtual returns (uint256);

    function balanceOf(address owner) external view virtual returns (uint256);

    function getAccountSnapshot(address account) external view virtual returns (uint256, uint256, uint256, uint256);

    function borrowRatePerBlock() external view virtual returns (uint256);

    function supplyRatePerBlock() external view virtual returns (uint256);

    function borrowBalanceStored(address account) external view virtual returns (uint256);

    function exchangeRateStored() external view virtual returns (uint256);

    function getCash() external view virtual returns (uint256);

    /**
     * @notice Indicator that this is a VToken contract (for inspection)
     * @return Always true
     */
    function isVToken() external pure virtual returns (bool) {
        return true;
    }
}
